#!/usr/bin/env python3
"""Enrich every included NPJ profile from cached publisher sources.

Only writes data/enrichment/npj.json. No raw abstract/full text is published.
Numeric/model/dataset extraction remains explicitly candidate/source_extracted;
human interpretation is restricted to the individually documented overrides.
Run: python3 scripts/enrich_npj_profiles.py
"""
from pathlib import Path
import json,re,sys,collections,concurrent.futures,os,subprocess
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
import npj_enrich as base
OLD=base.OLD;CACHE=base.CACHE

def compact(t):return re.sub(r'\s+',' ',t or '').strip()
def load(p,default):
 try:return json.loads(Path(p).read_text())
 except (OSError,ValueError):return default

def source(q):
 p=base.parse_publisher(base.cached_html(q['id'],q['url'],False),q['url'])
 abstract=next((v for k,v in p['sections'].items() if re.search('abstract',k,re.I)), '')
 sections={k:compact(v) for k,v in p['sections'].items() if re.search(r'^(?:Methods|Materials and methods|Results|Results and discussion|Discussion|Data availability|Code availability)$',k,re.I)}
 # Existing PDF text is read only; no network or cache modifications occur.
 f=next((x for x in [CACHE/(q['id']+'.txt'),OLD/'research-cache'/(q['id']+'.txt')] if x.exists()),None)
 text=f.read_text(errors='replace') if f else ''
 if not any(re.search('method',k,re.I) for k in sections):
  pdf_file=next((x for x in [CACHE/(q['id']+'.pdf'),OLD/'research-cache'/(q['id']+'.pdf')] if x.exists()),None)
  if pdf_file:
   # Reading order avoids right-column discussion/references interleaving with
   # left-column Methods in layout text. Extraction writes only to stdout.
   try:
    raw=subprocess.run(['pdftotext','-raw',str(pdf_file),'-'],capture_output=True,text=True,check=True,timeout=30).stdout
    if raw:text=raw
   except (OSError,subprocess.SubprocessError):pass
 # Only join genuine lower-case word continuations. An unrestricted join can
 # glue a right-column hyphen onto next-row "Methods" and erase the heading.
 text=re.sub(r'(?<=[a-z])-\n[ \t]*(?=[a-z])','',text)
 if len(re.findall(r'(?m)^\s*\d{1,4}\s{2,}(?=[A-Za-z])',text))>50:
  # Accepted manuscripts carry line numbers before otherwise genuine headings.
  text=re.sub(r'(?m)^\s*\d{1,4}\s{2,}(?=\S)','',text)
 text=re.sub(r'(?im)\n\s*\d{1,3}\s*\n\s*Article(?: in Press)?\s*\n','\n',text)
 text=re.sub(r'(?im)^.*(?:https?://doi\.org/10\.|npj Digital Medicine|Article in Press).*$','',text)
 text=re.sub(r'(?im)^\s*Article\s*$','',text)
 if text and not any(re.search('method',k,re.I) for k in sections):
  # Layout text can contain right-column bibliography. Stop at either heading
  # or an unambiguous numbered author reference; never search references.
  text=re.split(r'(?im)^\s*References\s*$|^\s*\d{1,3}\.\s+[A-Z][A-Za-z-]+,\s+[A-Z]',text)[0]
  heads=list(re.finditer(r'(?im)^\s*(?:\d+(?:\.\d+)*\.?\s+)?((?:Materials and )?Methods|Results(?: and discussion)?|Discussion|Data availability|Code availability)\b[^\n]*$',text))
  for i,m in enumerate(heads):
   name=m.group(1);end=heads[i+1].start() if i+1<len(heads) else len(text)
   body=compact(text[m.end():end]);body=re.split(r'\b(?:References|Received:|Acknowledgements|Author contributions)\b',body)[0]
   if body:sections[name]=body
 return p,abstract,sections,('publisher_pdf' if f and not any(re.search('method',k,re.I) for k in p['sections']) else 'publisher_html')

UNITS=r'patients?|participants?|individuals?|subjects?|adults?|children|infants?|women|men|cases?|controls?|(?:field.of.view )?images?|whole.slide images?|slides?|scans?|radiographs?|nodules?|videos?|recordings?|notes?|clinical notes?|reports?|records?|encounters?|admissions?|observations?|samples?|studies|trials|articles?|hospitals?|facilities|cent(?:er|re)s?|institutions?|clinicians?|physicians?|radiologists?|pathologists?|readers?|raters?|experts?|questions?|vignettes?|queries|prompts?|models?|datasets?|cohorts?|surgeons?|diaries|interviews?|consultations?|decisions?|cells|proteins?|sequences?|assessments?|evaluations?|scenarios|specialties|modalities|clients|rounds|messages?|documents?|devices?|manufacturers?|ratings?|hospitalizations?|examples?|benchmarks?|countries|compounds?|molecules?|experiments?|(?:virtual )?surgeries|publications?|platforms?|students?|ECGs?|LLMs?|FMs|MCQs|descriptors?|frames|pixels|hours|health systems'
NUM=r'\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?'
COUNTS=re.compile(r'(?<![\w.])('+NUM+r')\s*(million|billion|thousand)?\s+('+UNITS+r')\b',re.I)
SPELL={'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,'seventeen':17,'eighteen':18,'nineteen':19,'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90}
ROLE=[('External validation',r'external|independent cohort|held.out (?:clinic|hospital|site)'),('Prospective evaluation',r'prospective|consecutively enroll'),('Randomized intervention arm',r'randomi[sz]|intervention group|treatment arm'),('Training / development',r'train|develop|derivation|pre.train'),('Internal validation / test',r'internal validation|test set|testing cohort|hold.out'),('Reader / expert assessment',r'reader|rater|radiologist|pathologist|blinded|physician.rating'),('Review screening / inclusion',r'systematic review|screened|inclusion criteria|included studies'),('Synthetic / simulated experiment',r'synthetic|simulat|generated images'),('Screened / source population',r'screened|source population|eligible|database covers')]

def role(ctx):return next((name for name,pat in ROLE if re.search(pat,ctx,re.I)),'Source-reported count; cohort/overlap role requires checking')
def countfacts(text,section,url):
 out=[]
 for m in COUNTS.finditer(text):
  if re.search(r'\b(?:table|fig(?:ure)?|section|supplementary|appendix)\s*$',text[max(0,m.start()-30):m.start()],re.I):continue
  value=float(m.group(1).replace(',',''))*{'million':1e6,'billion':1e9,'thousand':1e3}.get((m.group(2) or '').lower(),1)
  if value<=0 or value>1e11 or not value.is_integer():continue
  value=int(value);ctx=text[max(0,m.start()-100):m.end()+100]
  if re.match(r'\s*(?:per|/)',text[m.end():m.end()+12],re.I):continue
  out.append(dict(value=value,unit=m.group(3).lower(),role=role(ctx),context=role(ctx),verified=False,source_section=section,source_url=url,verification='source_numeric_candidate'))
 for m in re.finditer(r'\b('+'|'.join(SPELL)+r')(?:[- ]('+'|'.join(SPELL)+r'))?\s+('+UNITS+r')\b',text,re.I):
  value=SPELL[m.group(1).lower()]+SPELL.get((m.group(2) or '').lower(),0);ctx=text[max(0,m.start()-90):m.end()+90]
  out.append(dict(value=value,unit=m.group(3).lower(),role=role(ctx),context=role(ctx),verified=False,source_section=section,source_url=url,verification='source_numeric_candidate'))
 for m in re.finditer(r'\b[Nn]\s*=\s*('+NUM+r')',text):
  value=float(m.group(1).replace(',',''));value=int(value) if value.is_integer() else value
  ctx=text[max(0,m.start()-90):m.end()+70]
  before=re.search(r'\b('+UNITS+r')\s*[\[(,:]?\s*$',text[max(0,m.start()-60):m.start()],re.I)
  after=re.match(r'\s*('+UNITS+r')\b',text[m.end():m.end()+40],re.I)
  unit=(before.group(1) if before else after.group(1) if after else 'reported n (unit unresolved)').lower()
  out.append(dict(value=value,unit=unit,role=role(ctx),context=role(ctx),verified=False,source_section=section,source_url=url,verification='source_numeric_candidate'))
 return out
METRIC=re.compile(r'\b(AUROC|AUC|AUPRC|AUCPR|accuracy|sensitivity|specificity|F1(?:[- ]score)?|BERTScore(?: F1)?|RMSE|MAE|C-index|Dice(?: score| coefficient)?|R²|R2|precision|recall|hazard ratio|odds ratio|κ|kappa)\b([^.;\n]{0,45}?)(?<![\d.])(0?\.\d+|\d+(?:\.\d+)?)\s*(%)?',re.I)
def metricfacts(text,section,url):
 out=[]
 def add(label,num,percent,start,end):
  value=float(num)
  bounded=bool(re.search(r'AUC|AUPRC|AUCPR|accuracy|sensitivity|specificity|F1|BERT|C-index|Dice|precision|recall',label,re.I))
  if bounded and not (0<=value<=(100 if percent else 1)):return
  if label.lower() in ['kappa','κ'] and not -1<=value<=1:return
  if label.lower() in ['r2','r²'] and value>(100 if percent else 1):return
  if label.lower() in ['hazard ratio','odds ratio','rmse','mae'] and (value<0 or percent):return
  out.append({'metric':label,'value':num+('%' if percent else ''),'comparison_role':'Endpoint, cohort and comparator unresolved; inspect source','verified':False,'source_section':section,'source_url':url,'verification':'Explicitly adjacent source metric/value; interpretation not manually checked'})
 for m in METRIC.finditer(text):
  between=m.group(2)
  # Accept explicit metric-value syntax only. Do not jump over clauses,
  # figure numbers or a value belonging to the next metric in a list.
  if not re.fullmatch(r"[\s:=,(\[]*(?:(?:of|was|is|were|are|reached|achieved|approximately|about|score|coefficient|an|a|mean|median|up|to|around|at|ranging|from|values|value|average|overall)[\s:=,(\[]*)*",between,re.I):continue
  if re.search(r'(?:\d+(?:\.\d+)?|0?\.\d+)\s*%\s*$',text[max(0,m.start()-22):m.start()]):continue
  add(m.group(1),m.group(3),bool(m.group(4)),m.start(),m.end())
 label=r'AUROC|AUC|AUPRC|AUCPR|accuracy|sensitivity|specificity|F1(?:[- ]score)?|BERTScore(?: F1)?|RMSE|MAE|C-index|Dice(?: score| coefficient)?|R²|R2|precision|recall|kappa'
 for m in re.finditer(r'(?<![\d.])(0?\.\d+|\d+(?:\.\d+)?)\s*(%)?\s+('+label+r')\b',text,re.I):
  add(m.group(3),m.group(1),bool(m.group(2)),m.start(),m.end())
 return out

