def dedupe(xs,key,limit):
 out=[];seen=set()
 for x in xs:
  k=key(x)
  if k not in seen:out.append(x);seen.add(k)
  if len(out)>=limit:break
 return out

def access_summary(text,urls,kind):
 text=compact(text)
 if re.search(r'not publicly|not public|cannot be (?:shared|made)|privacy|HIPAA|confidential|restricted',text,re.I):return {'status':'restricted_or_privacy_governed','summary':f'The source describes restrictions on {kind} access; consult its conditions and institutional approvals.','source_reported':True}
 if re.search(r'reasonable request|upon request|on request|request.*author',text,re.I):return {'status':'author_request','summary':f'The source describes author-mediated {kind} access; approval is not guaranteed.','source_reported':True}
 if urls or re.search(r'publicly available|open.access|GitHub|freely available|open.source',text,re.I):return {'status':'linked_or_public_repository','summary':f'The article names public or linked {kind} resources; each resource retains its stated license and access rules.','source_reported':True}
 if text:return {'status':'statement_present_conditions_unresolved','summary':f'A {kind} availability statement is present; access conditions need resource-level checking.','source_reported':True}
 return {'status':'not_resolved_from_extracted_statement','summary':f'The accessible extracted sections did not resolve {kind} access conditions. This is not evidence that no resource exists.','source_reported':False}
# Targeted, article-by-article interpretation of actual full-text sections.
# Indexes are resolved against the fixed included snapshot by explicit ID below.
MANUAL={}
def M(pid,question,method,finding,counts,limits,design=None):
 MANUAL['s41746-026-'+pid]=dict(research_problem=question,ai_method=method,study_summary=finding,counts=counts,limitations=limits,study_design=design or {})
M('03349-z','How can LLMs combine unstructured clinical text with structured EHR variables for patient-level prediction, and which integration strategies are supported by the literature?','Systematic evidence synthesis separating note embeddings, variable extraction and text-fusion approaches to LLM-enabled multimodal EHR prediction.','The 57 included studies used three integration patterns; the reported average improvement over single-modality comparators was 6.4%, with differing sample sizes and evaluation conventions.',[(641,'records','Literature screened'),(57,'studies','Included evidence synthesis')],['The study counts publications rather than independent patients or prospective deployments. Heterogeneous outcomes and comparators prevent treating the average gain as a universal clinical effect.'],{'design_group':'review','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03221-0','Can facial screening identify Turner syndrome under limited training data by combining learned appearance with clinically motivated facial geometry?','Deep facial features are fused with geometric priors and classified in the combined representation; prospective external testing follows retrospective development.','The external cohort yielded 95.41% accuracy, 96.55% sensitivity and 95.24% specificity. The reported 100% sensitivity concerns a difficulty-stratified training experiment, not all diagnostic settings.',[(1187,'participants','Retrospective development total'),(164,'Turner syndrome participants','Development subset'),(1023,'female controls','Development subset'),(218,'participants','Prospective external validation total'),(29,'Turner syndrome participants','External validation subset'),(189,'female controls','External validation subset')],['Facial screening is not equivalent to chromosomal confirmation. The smaller prospective cohort and difficulty-selected training analysis limit extrapolation to unselected populations.'],{'design_group':'prospective_validation','collection':True,'validation':True,'patient_rct':False,'reader':False})
M('03418-3','How accurately do deployed commercial algorithms detect dedicated and incidental pulmonary emboli across routine CT examinations, including subtle embolus subtypes?','Retrospective post-market evaluation of two Aidoc detection algorithms, with report-derived reference labels extracted by a separately validated LLM pipeline.','Dedicated-PE sensitivity/specificity were 86.8%/99.1%; incidental-PE values were 73.5%/99.8%. Sensitivity was lower for peripheral and non-acute emboli than for central acute disease.',[(30678,'CTPA examinations','Dedicated-PE evaluation; examinations are not unique patients'),(26288,'patients','Dedicated-PE source cohort'),(37191,'contrast CT examinations','Incidental-PE evaluation'),(28226,'patients','Incidental-PE source cohort'),(17,'facilities','Health-system sites'),(500,'examinations','Radiologist-annotated reference evaluation')],['This is retrospective diagnostic surveillance, not a patient-outcome trial. Most reference labels are report-derived, so LLM/reference-label error remains relevant.'],{'design_group':'retrospective','collection':False,'validation':False,'patient_rct':False,'reader':False})
M('03355-1','Does generative image enhancement integrated with puncture navigation improve the efficiency and safety of CBCT-guided lung biopsy?','GPS-Lung combines generative CBCT image improvement with procedure navigation; retrospective development is followed by a multicenter randomized biopsy comparison.','In the analyzed randomized groups, GPS-Lung reduced punctures, procedure time and radiation exposure. Pneumothorax occurred in 12.7% versus 23.9%.',[(3106,'patients','Retrospective CBCT development/evaluation total'),(2648,'patients','Retrospective development subset'),(458,'patients','Retrospective test subset'),(219,'patients','Analyzed randomized total in Results'),(110,'patients','GPS-Lung randomized analyzed arm'),(109,'patients','CBCT-only randomized analyzed arm'),(3,'centers','Randomized clinical study')],['Results analyze 219 randomized patients; a Methods enrollment passage states 309, so these denominators should not be silently equated. Trial registration occurred during the reported recruitment period. The accessible chronology does not independently resolve model freezing before accrual.'],{'design_group':'patient_rct','collection':True,'validation':None,'patient_rct':True,'reader':False})
M('03329-3','Can ensembles of histopathology foundation models distinguish Barrett esophageal morphology and identify adenocarcinoma across disease progression?','Multi-magnification features from five selected foundation-model backbones are aggregated and compared with expert-consistent single-model baselines.','The ensemble reported AUROC 0.907 for morphological subtyping and 0.909 for adenocarcinoma detection, with uneven improvement and persistent difficulty for dysplasia.',[(3528,'whole-slide images','BarrettNet evaluation images'),(790,'patients','Underlying BarrettNet participants'),(5,'foundation-model backbones','Selected ensemble members')],['The source cohort was prospectively assembled, but this model analysis reuses its slides. This is not prospective validation of a previously frozen classifier, and external confirmation is still required.'],{'design_group':'retrospective','collection':False,'validation':False,'patient_rct':False,'reader':False})
M('03211-2','Do automated similarity metrics measure clinical message quality, or primarily how faithfully clinicians edit the AI draft they can see?','A staged GPT-draft rollout compares displayed-and-edited drafts with silently generated drafts; lexical/semantic metrics are checked against blinded physician ratings.','BERTScore was 0.93 for incorporated drafts and 0.83 for independently written messages, but its correlation with clinical ratings depended on whether clinicians saw the draft. Human-authored messages were preferred in the blinded assessment.',[(30,'primary-care physicians','Deployment cohort'),(21073,'message drafts','Displayed intervention condition'),(45127,'message drafts','Silent non-displayed condition'),(2264,'drafts','Incorporated into final messages'),(120,'message pairs','Blinded quality assessment; 60 per condition'),(3,'physician raters','Blinded assessment')],['The groups arise from staged deployment rather than randomized patient assignment. Similarity to a draft and clinical usefulness are distinct endpoints; 120 rated pairs are not 120 trial patients.'],{'design_group':'reader','collection':False,'validation':False,'patient_rct':False,'reader':True})
M('03399-3','How do clinician expertise and deliberately flawed AI suggestions change diagnostic resilience when reading neonatal pneumoperitoneum radiographs?','A crossover reader experiment compares unaided interpretation, reliable AI and error-injected AI, assessing acceptance and override of algorithmic errors.','Trainees accepted 52.0% of incorrect suggestions under reliable AI. Three neonatologists overrode 91.7% of errors under flawed AI; this small specialist subgroup supports a hypothesis rather than a general clinical guarantee.',[(688,'radiographs','Model development images'),(216,'patients','Development source participants'),(125,'radiographs','Reader-study case set'),(14,'readers','Crossover participants'),(1750,'interpretation events','Reader decisions, not patients'),(3,'neonatologists','Specialist subgroup')],['Reader randomization and interpretation events do not constitute a patient RCT. Error injection is an experimental stress test, and the specialist subgroup is small.'],{'design_group':'reader','collection':False,'validation':False,'patient_rct':False,'reader':True})
M('03112-4','Can pretreatment imaging and clinical features identify lower-grade glioma patients likely to respond poorly to radiotherapy?','GUARD-LGG combines radiomic and clinical predictors, with internal, multicenter external and separately recruited prospective testing plus exploratory radiogenomics.','Reported AUCs were 0.946 in training, 0.929 internally, 0.882 externally and 0.913 in the prospective test set. Predicted unfavorable response also tracked shorter survival.',[(674,'patients','Training'),(289,'patients','Internal validation'),(187,'patients','External validation across seven institutions'),(328,'patients','Prospective test cohort'),(7,'institutions','External test sites')],['Response discrimination does not establish that using the score to choose radiotherapy improves outcomes. The prospective cohort is model testing rather than randomized AI-guided treatment; model freezing before its accrual is not resolved in the reported chronology.'],{'design_group':'prospective_collection','collection':True,'validation':None,'patient_rct':False,'reader':False})
M('03421-8','Can a single structured LLM call generate complete OSCE stations that faculty judge usable across diagnoses and learner levels?','Schema-constrained LLM generation produces instructions, standardized-patient scripts and marking schemes, followed by structured internist ratings.','All generated cases passed schema validation; experts rated overall value highly, while guideline concordance and difficulty calibration showed weaker agreement.',[(24,'OSCE cases','Generated and evaluated stations'),(8,'diagnoses','Content coverage'),(3,'learner levels','Educational strata'),(3,'internist raters','Expert assessment')],['Expert acceptability is not evidence of learner benefit, examination validity or equivalence to faculty-written stations. Faculty oversight remains necessary.'],{'design_group':'reader','patient_rct':False,'reader':True,'collection':False,'validation':False})
M('03417-4','Can an offline learned policy identify session-level rTMS choices associated with improved depression symptoms in held-out clinics?','Reinforcement learning uses longitudinal clinical decisions and subsequent PHQ-9 change to recommend stimulation type, intensity and laterality; policy value is assessed observationally.','Matching recommendations was associated with 0.788 points greater next-session improvement in held-out clinics. The projected 3.22-point episode benefit is a model-based estimate, not an observed randomized treatment effect.',[(1609,'patients','Retrospective analytic cohort'),(56939,'treatment-decision rows','Longitudinal repeated decisions'),(19,'clinic groups','Source settings'),(370,'patients','Held-out clinic test cohort'),(14074,'decision rows','Held-out test decisions'),(325,'patients','Internal validation cohort')],['Confounding by treatment selection and reward specification remain unresolved. Retrospective policy evaluation does not establish prospective clinical efficacy.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03392-w','Can a one-year OUD risk model transfer across changing EHR vocabularies and independent national healthcare systems?','OUD-REY learns longitudinal EHR histories and uses pretrained language representations to harmonize previously unseen clinical features across datasets.','Internal AUROC was 0.912; temporal All of Us and VA validation AUROCs were 0.864 and 0.855, with substantially lower precision-recall values under their low OUD prevalences.',[(24564,'participants','Balanced development sample'),(4564,'OUD cases','Development subset'),(20000,'controls','Development subset'),(75694,'patients','Temporal All of Us validation'),(5832560,'patients','VA eligible source cohort'),(4762354,'patients','VA reported clinical-history subgroup analysis')],['VA source-cohort size and analysis-subgroup size describe different denominators. Retrospective transfer and fairness audits do not prove benefit from clinical deployment.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03396-6','Does an LLM-generated preparation summary reduce perceived workload when clinicians prepare real oncology consultations?','AI-FCP structures unstructured documentation; a prospective single-group pre/post usability study combines clinician-level baselines and consultation-level follow-up.','Perceived workload fell by 28.9%, with self-reported savings of 3.26 minutes per case. Preparation succeeded in 84.9% of consultations, and 63.6% of summaries were complete.',[(9,'clinicians','Person-level baseline'),(6,'clinicians','Contributors of consultation-level evaluations'),(33,'consultations','AI-supported consultation observations'),(20,'assessments','Detailed consultation-level timing assessments')],['The uncontrolled, small study has unequal case contribution and possible scheduling/survivorship bias. Perceived time savings are not a controlled productivity or patient-safety effect.'],{'design_group':'prospective_collection','patient_rct':False,'reader':False,'collection':True,'validation':False})
M('03388-6','Do LLM scores from brief daily video diaries capture depression variation beyond self-report surveys?','LLMs rate transcribed diaries; multilevel and multivariable analyses compare within-person changes and person-level averages against surveys, interviews and daily functioning.','LLM scores correlated with within-person self-report variation (r=0.45), averaged self-report (r=0.61) and interview severity (r=0.53), and retained associations beyond self-reports.',[(108,'participants','Diary and clinical-assessment cohort'),(14,'days','Shorter diary protocol duration'),(21,'days','Initial diary protocol duration')],['Repeated days and diary entries are not independent participants. Convergent validity in this selected cohort does not establish diagnostic replacement or outcome benefit.'],{'design_group':'prospective_collection','patient_rct':False,'reader':False,'collection':True,'validation':False})
M('03323-9','Can pulmonary-nodule risk estimates remain discriminative and calibrated when CT acquisition characteristics and populations change?','A shared 3D encoder and acquisition metadata form cohort prototype relations; Gromov–Wasserstein alignment feeds a distributionally robust calibration-aware risk head.','External AUC improved from 0.857 to 0.878 and calibration error fell from 0.106 to 0.066 relative to the strongest reported imaging baseline.',[(1842,'nodules','LIDC-IDRI development total'),(642,'nodules','Development acquisition cohort 1'),(603,'nodules','Development acquisition cohort 2'),(597,'nodules','Development acquisition cohort 3'),(618,'nodules','External LNDb validation'),(612,'nodules','Resampled protocol-shift experiment; overlaps underlying held-out scans')],['Nodule counts are not unique-patient counts. Prospective pathology-confirmed evaluation is still needed, and simulated protocol shifts are not new prospective acquisitions.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03381-z','Can a single publicly trained text-guided generator cover diverse medical imaging tasks and help classifiers in data-limited settings?','MediSyn uses a generalist latent-diffusion model, compared with specialty-specific generators, physician realism assessments and downstream classifier augmentation.','The generalist model produced competitive text-aligned images across specialties, reduced generation overhead and improved selected data-limited classifiers; synthetic images remained distinguishable from training images in similarity analyses.',[(6,'medical specialties','Generator coverage'),(10,'imaging modalities','Generator coverage'),(10000,'generated images','Inference-time benchmark workload')],['The 10,000-image workload is not the training cohort or a patient count. Synthetic-image realism and classifier augmentation do not establish clinical utility, and rare/unseen conditions remain challenging.'],{'design_group':'other','patient_rct':False,'reader':True,'collection':False,'validation':False})
M('03357-z','Can routine structural MRI distinguish parkinsonian disorders without the acquisition burden of research-grade multimodal imaging?','A hierarchical discovery/verification/translation pipeline derives a T1-Top20 machine-learning signature, freezes it for external testing and transfers it to anisotropic clinical MRI.','The T1 model achieved multiclass AUROC 0.93, external PD-versus-MSA AUROC 0.88 and clinical-MRI AUROC 0.84; it identified 19 of 25 observed iRBD phenoconverters.',[(969,'participants','Multicenter analysis total'),(227,'participants','External research-grade cohort'),(303,'participants','Clinical-MRI translation cohort'),(107,'participants','Exploratory iRBD cohort'),(25,'phenoconverters','Observed iRBD-to-PD subgroup'),(19,'phenoconverters','Correctly identified subgroup')],['Freezing before analysis of an existing cohort does not itself establish prospective model validation. Phenoconversion findings concern a small exploratory subgroup.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03341-7','How can LLM-extracted substance-use diagnoses be checked at scale when exhaustive expert annotation is impractical?','Prompt calibration, structural filtering, semantic grounding, judge-LLM review, expert checks and downstream predictive validity form a staged weak-supervision validation pipeline.','Filtering removed 14.59% of initially positive extractions. The primary extractor achieved F1 0.80 against judge evaluations, and extracted diagnoses predicted subsequent specialty care beyond structured-code baselines.',[(178467,'patients','Underlying clinical cohort'),(919783,'clinical notes','Extraction corpus'),(11,'substance categories','Diagnostic extraction targets')],['Judge-LLM labels are not a universal human gold standard. Expert review covers selected uncertain cases, leaving correlated model error and generalizability to other systems unresolved.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03377-9','Can training-free agent collaboration reason over years of EHR events to estimate near-term risk for multiple cancers?','TrajOnco chains LLM agents with long-term memory to summarize temporal events, cite evidence and estimate one-year cancer risk; matched case-control tests compare with single-agent and supervised baselines.','Across 15 cancers AUROCs ranged from 0.64 to 0.80; temporal reasoning improved over single-agent configurations, with interpretable but imperfect rationales.',[(15,'cancer types','Prediction targets'),(500,'cases per cancer','Matched evaluation sample; cross-cancer uniqueness not established'),(500,'controls per cancer','Matched evaluation sample; not population prevalence'),(21308,'cases','Separate supervised benchmark development'),(20863,'controls','Separate supervised benchmark development'),(30,'patients','Human rationale evaluation'),(113,'events','Reviewed reasoning events')],['Balanced case-control evaluation does not directly estimate population positive predictive value. Cohorts across cancer targets must not be summed as unique individuals; this is retrospective risk discrimination.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03319-5','Can collaborating LLM agents generate optimization code that produces feasible, efficient operating-room schedules?','Specialized iterative agents formulate and revise mixed-integer scheduling code, with synthetic scenarios, real surgical datasets and expert-written optimization comparators.','Average feasible-schedule rates were 82.91% for the iterative system versus 65.59% and 52.53% for baselines; generated solutions approached expert-programmed optimization performance.',[(10,'LLMs','Evaluated models'),(35,'scenarios','Scheduling conditions'),(1050,'synthetic instances','Simulation workload'),(3,'real OR datasets','Source evaluation datasets'),(40615,'patients','West China source surgical dataset')],['Synthetic scheduling instances, source patients and optimized schedules are different units. Retrospective operational improvements are not prospective evidence of reduced cancellations or patient harm.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03275-0','Can an end-to-end system extract, standardize and prioritize rare-disease phenotypes from clinical notes rather than optimizing these steps separately?','RARE-PHENIX combines LLM extraction, ontology-grounded HPO standardization and supervised phenotype ranking, followed by independent clinical-note evaluation.','The pipeline improved concordance with curated HPO profiles and provided exploratory downstream disease-prioritization signal; the clinically diagnosed subset was much smaller than the note corpus.',[(2671,'patients','UDN training cohort'),(11,'UDN clinical sites','Development settings'),(143,'patients','External VUMC validation'),(16357,'clinical notes','External note corpus'),(29,'patients','Confirmed-diagnosis downstream evaluation subset')],['Thousands of notes do not represent thousands of independent external patients. Disease-ranking analysis uses only 29 confirmed cases, and clinician oversight remains necessary.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03296-9','Which design, implementation and governance requirements do experts consider essential for neuroimaging AI in memory clinics?','A three-round Delphi consensus process gathers clinical, academic and industry views with patient/public involvement.','The panel agreed eight statements across purpose, quality, clinical interaction, privacy and ethics, providing implementation guidance rather than a new diagnostic accuracy estimate.',[(16,'experts','Delphi panel'),(3,'questionnaire rounds','Consensus process'),(8,'statements','Consensus outputs')],['Consensus reflects a small selected expert panel and is not validation of a particular model, a patient cohort or a treatment effect.'],{'design_group':'other','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03291-0','What evidence and integration gaps remain when AI monitoring, wearable sensing and smart infusion delivery are combined?','Narrative review of AI-enabled monitoring and infusion automation, culminating in the conceptual INFUSYNC integration architecture.','The review describes promising sensing and delivery components but finds many AI infusion systems remain prototypes, with uncommon closed-loop control and unresolved interoperability/security. ',[],['INFUSYNC is a conceptual framework rather than a tested patient intervention. The article does not provide one enrolled cohort or a clearly enumerated systematic-review inclusion denominator.'],{'design_group':'review','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03281-2','Can hospitals collaboratively pretrain gastrointestinal endoscopy representations while keeping image data local?','Federated masked-autoencoder/foundation-model training is compared under homogeneous and heterogeneous client distributions and transferred to classification, detection and segmentation.','Federated representation learning improved reported downstream performance across settings, with experiments varying client count and pretraining strategy.',[(87970,'images','HyperKvasir selected for pretraining'),(37876,'images','Kvasir-Capsule selected for pretraining'),(8000,'images','Gastrovision downstream dataset'),(386,'images','EDD2020 downstream dataset'),(5,'clients','Main federated training configuration')],['The client distributions are experimental federated configurations, not a prospective hospital deployment. Different source-image datasets and downstream partitions should not be summed as unique patients.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03265-2','Do the order, recency and speed of hospital diagnoses add prognostic information beyond age and aggregate comorbidity burden?','A contrastively trained visit-level transformer encodes diagnosis sequences and admission timing; embeddings are compared with Elixhauser-based risk models across mortality and disease outcomes.','Mortality AUC increased from 0.866 to 0.879; gains across incident conditions were modest and heterogeneous. Residual embedding risk separated subsequent event-free survival among otherwise similar patients.',[(7418519,'patients','Representation-learning source population'),(1734479,'patients','Downstream outcome cohort; subset rather than additional population'),(130,'disease-block outcomes','Prediction targets'),(13,'years','Source inpatient-history span')],['Hospital-only records incompletely observe outpatient morbidity. Modest discrimination gains and observational survival separation do not establish intervention benefit.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03397-5','How strongly do prompt strategies and model choice interact when LLMs answer traditional Chinese medicine licensing questions?','Sixteen LLMs are tested under seven prompting strategies using a public examination benchmark, with paired prompt analysis and focused error classification.','Unprompted accuracy ranged from 35.4% to 85.9%; average prompt gains were small, while individual models sometimes improved markedly or deteriorated. No prompt reliably helped all models.',[(16,'LLMs','Model benchmark'),(475,'questions','2025 Taiwan TCM licensing examination'),(7,'prompt strategies','Prompt comparison'),(5,'models','Selected lower-performing error-analysis subgroup')],['Exam questions are not patient encounters. Model-family comparisons are descriptive with only 16 versions, and prompt effects cannot be generalized across models without testing.'],{'design_group':'other','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03379-7','Can an interpretable neural scoring system stratify advanced-melanoma prognosis across treatment regimens and independent trials?','ScoreNet learns an additive, eight-feature risk score for overall and progression-free survival, then checks stratification in separate trial datasets.','The score separated low-, intermediate- and high-risk groups across multiple treatment classes and retained prognostic stratification in two external trials.',[(2711,'patients','Pooled development cohort'),(5,'trials','Development data sources, not new randomized AI trials'),(945,'patients','CHECKMATE-067 external validation source'),(921,'patients','COLUMBUS external validation source'),(8,'baseline features','Final interpretable score')],['Reanalysis of RCT data does not make the scoring-model study a patient RCT. Prognostic separation does not establish that score-guided treatment selection improves survival.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03368-w','Can multidimensional CGM patterns reveal diabetes subtypes and complication risks that conventional time-in-range measures miss?','The study combines CGM-derived metrics, Gaussian-mixture phenotyping and predictive glycemic risk scoring within the iCanNet cohort.','Distinct diabetes signatures and four T2D phenotypes emerged. The risk score reassigned some conventionally well-controlled patients to higher complication-risk groups.',[(90757,'participants','iCanNet study population'),(48,'CGM metrics','Candidate glycemic features'),(14027,'T2D participants','Chronic-complication analysis cohort'),(10588,'participants','Repeated-measurement consistency subset'),(4,'phenotypes','T2D mixture-model groups')],['Source participants, repeated records and outcome-specific subsets overlap. Retrospective phenotyping/reclassification does not prove improved outcomes from CGM-score-guided management.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03290-1','Can operational governance logic route retraining and post-market model updates to explicit approval, review or rejection states?','AEGIS joins data assimilation, retraining, monitoring and conditional decisions, instantiated with sepsis prediction and brain-tumor segmentation plus constructed failure scenarios.','Experiments exercised all decision categories and routed unsafe/no-deployable-model states to rejection with alarm. Cross-site covariate-shift discrimination improved, but concept drift was not evaluated.',[(20336,'patients','PhysioNet Hospital A source cohort'),(4067,'patients','Held-out sepsis evaluation'),(8134,'patients','Initial sepsis training'),(200,'subjects','Held-out BraTS evaluation'),(1150,'subjects','BraTS training')],['This is a proof-of-concept governance simulation, not regulatory approval or prospective clinical safety validation. Constructed failure batches and covariate drift do not cover all real model failures.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03378-8','Do neighborhood social determinants improve hourly emergency-demand forecasts beyond weather and temporal features?','XGBoost combines time-varying population vulnerability and environmental predictors, with feature interpretation and alternative predictor-set comparisons.','The composite model reported RMSE 3.48 visits/hour, MAE 2.62 and R-squared 0.68, with social-vulnerability features more informative than weather-only inputs.',[(213138,'ED encounters','Underlying visits; not unique people'),(22883,'hourly observations','Forecasting analysis rows'),(1,'hospital','Single-center Wuhan source')],['Visits and hourly aggregate rows are not independent patients. Single-center retrospective forecasts require prospective operational testing before staffing or crowding benefits can be claimed.'],{'design_group':'retrospective','patient_rct':False,'reader':False,'collection':False,'validation':False})
M('03369-9','How do patients, caregivers and hospital staff perceive proposed AI and other digital solutions for discharge coordination?','CFIR-informed deductive/inductive analysis of stakeholder interviews about six candidate technologies, including AI bots and discharge-summary drafting.','Participants emphasized visible workflow value, integration and preservation of human contact, alongside safety, privacy, equity and accountability concerns; eleven subthemes were identified.',[(47,'people','Screened'),(43,'interviewees','Participated'),(25,'staff','Interview subgroup'),(14,'patients','Interview subgroup'),(4,'caregivers','Interview subgroup'),(6,'candidate technologies','Discussed solutions')],['Interview responses concern proposed technologies rather than measured performance of deployed AI. Purposive sampling and one service-improvement context limit transferability.'],{'design_group':'other','patient_rct':False,'reader':False,'collection':True,'validation':False})
M('02514-8','Can a multi-agent assistant turn preventive-care recommendations into locally appropriate, personalized diet and exercise plans that residents and clinicians find usable?','HealthGuide@Home uses agent collaboration, semantic routing and trusted local information to draft and iteratively customize preventive-health plans.','Residents and clinicians generally rated appropriateness and usefulness above neutral, with favorable feedback on personalization. The pilot establishes preliminary acceptability rather than disease-prevention efficacy.',[(20,'residents','Pilot user cohort'),(7,'clinicians','Pilot expert/user cohort')],['This small exploratory acceptance study does not demonstrate behavior change, adherence or long-term clinical outcomes. Resident and clinician assessments are distinct units.'],{'design_group':'prospective_collection','patient_rct':False,'reader':False,'collection':True,'validation':False})

ABSTRACT_MANUAL={}
def A(pid,question,method,finding,limit):
 ABSTRACT_MANUAL['s41746-026-'+pid]=dict(research_problem=question,ai_method=method,study_summary=finding,limitations=[limit])
A('03314-w','Can one agentic system annotate several clinical communication frameworks across specialties?','MOSAIC combines retrieved examples, dynamic few-shot prompts and planning/verification agents.','Development used 54 transcripts and testing used 120; weighted F1 was 95.6% against trained coders.','Results cover two specialties and coder agreement, not downstream improvements in clinical communication.')
A('03373-z','Can ambient oncology conversations support reliable automatic toxicity grading?','VOICE-AE links speech recognition, speaker separation and LLM-based CTCAE extraction.','Among 31 patients and 39 encounters, exact grading agreement was 82.6%, but grade-zero dominance inflated overall accuracy and actionable-grade F1 was lower.','Severe-toxicity detection and clinical safety remain unproven in this small, imbalanced sample.')
A('03348-0','Does grounded memory improve LLM agents performing structured clinical data operations?','FHIR-AgentEval runs deterministic server-state checks on 43 workflow tasks and ablates five memory/specification configurations.','The best memory configuration improved held-out success by 9.1% over baseline.','Sandbox task completion does not establish reliability in live hospital integrations.')
A('03391-x','How mature are real radiation-oncology AI deployments in resource-constrained countries?','A systematic review classifies 18 studies by workflow integration and governance readiness.','Most reports concerned isolated tasks; one reached cross-stage orchestration, and none demonstrated the highest autonomy level.','Predominantly retrospective validation and absent continuous monitoring constrain claims about scalable safe deployment.')
A('03387-7','Can first-day routine measurements identify septic patients likely to remain in intensive care beyond four days?','FT-TabNet adaptively fuses tabular representations from 17 SOFA-related features, with SHAP interpretation.','AUROC was 0.848 internally and 0.823/0.781 in two Korean external cohorts.','External performance varied; prediction does not demonstrate improved allocation or shorter ICU stays.')
A('03376-w','How does generative AI change collaboration among faculty teaching clinical biostatistics?','Two-year action research combines teacher reflections, AI-assisted semantic coding and network analysis of 4,697 messages.','Faculty roles shifted toward facilitation; AI-related relationships were selective but reciprocal and locally clustered.','The curriculum-level observational design does not isolate AI effects on student competence.')
A('03375-x','Can robotic-console measurements support reproducible surgical skill scores?','Nineteen kinematic indicators undergo PCA and ridge-logistic scoring across procedure tasks.','The study analyzed 2,588 tasks from 392 cases; external attending-versus-trainee AUC was 0.84 in 21 cases.','The external cohort contains only 21 procedures; expertise discrimination does not establish a causal relationship with patient outcomes.')
A('03350-6','Can LLM-assisted scoring scale assessment of open-ended diabetes precision-medicine learning?','An online course evaluation pairs pre/post learning measures with consensus LLM scoring checked against human ratings.','Among 435 completers, scores improved; 300-response validation showed 75.3% exact and 99.3% adjacent agreement.','An uncontrolled completer cohort cannot establish causal educational benefit, and adjacent agreement can conceal scoring discrepancies.')
A('03333-7','Can routine chest radiographs identify people who should receive bone-density testing?','AI-OsRM uses masked-autoencoder pretraining and a ResNet predictor trained against paired DXA examinations.','Development included 46,478 examination pairs from 26,757 patients; external osteoporosis AUROCs were 0.88–0.93.','The reported reduction in DXA use is simulated, rather than an observed screening-pathway effect.')
A('03325-7','Do increasingly complex generalist-agent workflows reliably improve multimodal diagnosis?','Ten GPT-5 configurations are compared on 161 clinician-validated cases for reasoning, retrieval and image interpretation.','Complex retrieval sometimes degraded performance; image understanding and evidence integration remained inconsistent despite useful reasoning capabilities.','Curated case evaluation does not establish safe autonomous diagnosis in unselected clinical populations.')
A('03365-z','Do existing health-technology assessment rules accommodate generative AI uncertainty and adaptation?','A comparative document analysis examines 56 guidance documents across six health systems.','Guidelines favor trials and cost-effectiveness analysis but provide limited specific treatment of stochastic, evolving model behavior.','Document recommendations are not evidence that a particular assessment method ensures clinical safety or value.')
A('03346-2','Can clinical-note models distinguish epilepsy from psychogenic seizure presentations earlier?','EpiScreen fine-tunes language models and compares standalone predictions with neurologist-assisted assessment.','Reported AUC reached 0.875 in MIMIC-IV and 0.980 in a private cohort; assistance improved the evaluated neurologist task.','Screening and assisted-case performance do not replace video-EEG confirmation or prove reduced diagnostic delay.')
A('03305-x','Can noninvasive multimodal data distinguish pulmonary arterial hypertension from left-heart-related pulmonary hypertension?','An adaptive graph network integrates CT and clinical variables through learned graph construction, cross-modal attention and contrastive learning.','Repeated cross-validation of 905 patients yielded mean AUC 0.946, but calibration slope suggested recalibration was needed.','There was no prospective external validation; catheterization should not be replaced on this evidence.')
A('03243-8','Can temporally explicit EHR representations reduce missed medication-safety alerts at ordering time?','ClinicalGPT encodes time, units, provenance and observability with hard clinical constraints.','Across 847,000 orders from seven systems, missed alerts were 3.2 per thousand versus 9.4 for rules; a silent study assessed workflow separately.','Offline alert misses are process outcomes, not adverse drug events or prevented patient harm.')
A('03180-6','Can generative motion modeling screen infants when expert-labeled abnormal examples are scarce?','DeepAD learns infant movement patterns through temporal autoregression and reconstruction.','More than 1,300 videos from three hospitals included approximately 50 cerebral-palsy infants; experiments reported performance comparable with experts.','Videos and infants are different denominators; screening capability does not establish earlier treatment or improved development.')
A('03352-4','Can multimodal AI serve as the first grading pass during routine medical-student OSCE operations?','MAPLES applies zero-shot rubric-based LLM scoring to notes, audio and video with routed human review.','Deployment covered 222 students and 72,907 item scores; tolerant agreement was high in selected review sets.','Adjudication exposed score provenance, and workload savings used a modeled comparator; educational deployment is not frozen-model clinical validation.')
A('03343-5','Can staged pretraining produce CT representations transferable across imaging tasks and scales?','FlexiCT progresses from axial learning to 3D anatomy and report-aligned semantics.','Training used 266,227 volumes from 56 public datasets; evaluation covered segmentation, classification, registration and language/retrieval tasks.','Benchmark transfer and disease-associated embeddings do not establish prospective clinical benefit.')
A('03339-1','Does longer AI-assisted home rehabilitation improve early Parkinson motor outcomes?','A randomized, rater-blinded comparison assigns 120 patients to one-, two- or three-month telerehabilitation schedules.','Only 71 entered final analysis; the primary motor endpoint did not differ, and a cognitive responder signal was exploratory.','High attrition, no usual-care arm and post-hoc cognitive analysis prevent strong causal or efficacy claims.')
A('03336-4','Can an examiner-conditioned second marker identify inconsistent VR-OSCE grading?','RAVEN fuses video, examiner speech/marks and action logs, using confidence-gated human–AI decisions.','Retrospective evaluation included 120 students and 442 ratings; pass/fail agreement with panel consensus improved by 6.2 points.','Panel agreement is not an external competence gold standard; the tool supports audit rather than autonomous grading.')
A('03335-5','What diagnostic-error levels do members of the public consider acceptable for medical AI?','Surveys translate tolerated missed and false-positive cases into minimum sensitivity/specificity values.','Across 1,222 general respondents and 106 lung-cancer survivors, mean minimum values were approximately 0.90; cancer history tracked stricter expectations.','Hypothetical preferences are not actual uptake, predictive values or a universal clinically optimal threshold.')
A('03331-9','Can agents translate quantitative brain-tumor morphology into clinically recognizable imaging signs?','An autonomous radiomics-to-semantics pipeline generates candidate signs, followed by independent radiologist assessment.','From 106 glioblastomas it proposed eight signs; external cauliflower-sign AUC averaged 0.75 across two readers and 100 tumors.','A small external differentiation task does not establish universal sign reproducibility or treatment value.')
A('03330-w','How do users seek explanations and manage uncertainty when discussing home ECG results with an LLM?','Retrospective conversational analysis tracks intents, concerns and repair behavior in an AI-ECG explanation system.','The corpus contains 109,017 sessions and 323,470 turns from 26,419 users; requests broadened from interpretation toward action and health management.','Engagement trajectories are not evidence of diagnostic accuracy, safe self-management or improved health outcomes.')
A('03321-x','Can retrieval and specialized agents improve hyperthyroidism admission histories without introducing unsupported facts?','HQ-ANR grounds Qwen3-32B in guidelines and expert notes, assigning symptom, examination and treatment agents.','In 30 notes, documentation scores improved and positive factual hallucinations fell to 6.67%, with approximately 113 seconds less physician refinement.','Small-note evaluation and a restricted hallucination definition leave broader error rates and deployment safety unresolved.')
A('03317-7','Are mental-health LLM evaluations aligned with intended tasks and clinically meaningful outcomes?','An HCI-oriented scoping review maps 84 studies across stakeholders, interactions and evaluation domains.','Technical evaluation predominated; only three randomized trials and limited longitudinal follow-up were identified.','Technical response quality cannot be substituted for symptom improvement, crisis safety or sustained clinical effectiveness.')
A('03316-8','Can accessible biopsychosocial measurements summarize future vulnerability across diseases?','RS4DV uses LightGBM with 85 features, then derives a six-item approximation and examines cross-cohort transfer.','Discovery/test cohorts comprised 391,193/90,864 people; baseline scores stratified disease progression and mortality in initially diagnosis-free participants.','Prediction from existing longitudinal cohorts does not imply prospective evaluation of a deployed frozen model or benefits from score-guided prevention.')
A('03359-x','Can patient narratives yield chronic-pain measurements beyond conventional questionnaires?','LLMs score sensory, affective and social dimensions and derive narrative constructs such as agency.','The study reports convergence with conventional measures while capturing assessor-dependent aspects of personal narrative.','The abstract does not resolve cohort size or establish diagnostic replacement, intervention responsiveness or clinical benefit.')
A('03318-6','Can reporting checklists be checked at individual-element rather than whole-item level?','A 200-article annotated corpus supports PubMedBERT evidence retrieval followed by GPT-5 question answering.','The 119-question pipeline achieved F1 0.822; evidence-retrieval quality strongly influenced performance.','Most articles received single-annotator assessment, and checklist completeness does not establish trial validity or absence of bias.')
A('03273-2','Can calibrated models identify which GLP-1 adverse-event reports are classified as serious?','Interpretable prediction and post-hoc calibration are applied to 242,312 FAERS reports.','AUCs ranged from 0.877 to 0.930; common gastrointestinal events contributed less than dosing, injection-site and pancreatic signals.','Spontaneous reports and reporter-defined seriousness do not establish incidence, causation or comparative drug safety.')
A('03268-z','Can digital-exclusion classifiers transfer across older-adult populations internationally?','Harmonized data from five cohorts are analyzed using boosting, logistic regression and leave-one-cohort-out validation.','Among 71,689 adults, boosting AUCs were 0.734–0.850 but scarcely exceeded logistic regression; transportability was partial.','Concurrent nonuse is a limited participation proxy, and cross-sectional depression associations do not establish prospective individual risk.')
A('03356-0','How often can users find public performance evidence for authorized pathology and hematology AI software?','A multi-source regulatory landscape review links 77 devices from 29 manufacturers to device-specific evidence.','Public evidence was found for 30 devices; heterogeneous metrics impeded direct cross-device comparison.','Failure to find public evidence does not establish that regulators or manufacturers performed no evaluation.')
A('03332-8','Can an uncertainty-aware eye-care LLM improve understandable screening guidance and referral adherence?','EyeSeek combines abstention-driven iterative learning with role-specific explanations and expert/user evaluation.','A prospective single-center comparison included 84 assisted and 86 unassisted residents, with higher adherence in the assisted group.','The abstract does not establish randomized assignment or effects across multiple centers; readability is distinct from clinical safety.')
A('03232-x','Can a structured history-taking agent improve ophthalmic pre-consultation compared with resident interviews?','A dual-agent system uses symptom logic trees in a randomized comparison of 172 patients.','History quality improved by 17.7 points, but interactions were longer; examination findings narrowed diagnostic differences.','Single-center non-emergency appointments limit generalization, and better documentation is not equivalent to improved patient outcomes.')
A('03324-8','Are clinical Shapley explanations reported and interpreted well enough to support their claimed uses?','A methodological scoping review examines 100 randomly selected clinical prediction publications.','Ninety-one percent omitted the computation algorithm and 97% omitted baseline-population details, undermining reproducibility.','Explanations of model predictions are not causal feature effects or independent guarantees of trustworthy clinical decisions.')
A('03272-3','Can example retrieval improve interpretable breast-ultrasound categorization across institutions?','B-RAD aligns BI-RADS representations, retrieves exemplars, localizes/segments lesions and focuses classification on the lesion.','Across 8,311 images in eleven cohorts, independent-institution triage AUC was 0.952; assistance improved four readers.','Reader gains and external retrospective discrimination do not demonstrate prospective screening benefit or population-level harm reduction.')
A('03252-7','Can reproducible abstract-level surveillance describe a rapidly growing AI-oncology literature?','OncoTagger combines rule-based extraction with manual adjudication and weighted error estimation.','From 59,994 records it retained 20,766; task agreement was moderate despite stronger metric detection.','The resource is a selected open-access corpus, not a complete field census or validated paper-level comparative performance assessment.')

A('03227-8','Can brain MRI encode body-mass-associated changes relevant to non-neurological disease?','Deep models predict BMI across six cohorts and link learned signatures to longitudinal weight change and systemic diagnoses.','Within-cohort prediction exceeded external performance; brain-derived signatures discriminated cardiometabolic and respiratory conditions beyond BMI itself.','Cross-cohort attenuation and observational associations leave causal mechanisms and clinical utility unresolved.')
A('03328-4','Can brief stress narratives distinguish sustained vulnerability among healthcare workers?','A hierarchical transformer fuses linguistic, acoustic and facial embeddings against longitudinal symptom clusters.','Of 750 invited workers, 553 contributed sufficient data; multimodal held-out AUC was 0.75 versus 0.63 for language alone.','The clusters derive from self-reports, and prospective collection does not establish prospective deployment validation.')
A('03320-y','Do LLM discharge summaries preserve information important to receiving clinicians after longer admissions?','Paired clinician review compares generated and human summaries for 60 hospitalizations lasting 7–21 days.','Reviewers preferred AI summaries in 95% of encounters and annotated fewer omissions, without significant differences in estimated harm.','Retrospective reviewer preference is not observed patient safety or improved continuity of care.')
A('03261-6','Can a compact predictor stratify three-year mortality in cardiovascular–kidney–metabolic syndrome?','XGBoost and LASSO are developed on 101 variables, yielding an eight-variable boosting model.','Among 219,561 hospitalized patients, center-based validation AUC was 0.813 and high-score groups had substantially higher mortality.','Retrospective discrimination and score-associated hazards do not establish benefits from calculator-guided management.')
A('03256-3','Which low-power wireless designs suit different wearable monitoring constraints?','A technical review compares RFID, NFC, backscatter and ultra-wideband architectures for physiological sensing.','The review organizes trade-offs in power, range, integration and security rather than validating an AI clinical model.','The abstract does not establish substantive AI; biomedical sensing hardware alone warrants eligibility re-screening.')
A('03361-3','Does disclosing AI use change how people judge primary-care physicians?','A vignette experiment varies AI disclosure and physician demographics in advertisements rated by 1,030 participants.','AI disclosure reduced warmth, competence and appointment willingness; younger respondents showed larger penalties.','Fictitious advertisement judgments are not actual appointments or evidence about clinical performance.')
A('03338-2','What professional concerns shape clinical adoption of AI recommendations?','A qualitative meta-synthesis interprets 13 studies from nine countries through Normalization Process Theory.','Participants valued efficiency but described opacity, accountability, autonomy, privacy and equitable-allocation concerns.','Synthesized perceptions identify implementation issues, not measured safety or effectiveness of particular systems.')
A('03327-5','How mature is AI-based interpretation of viscoelastic coagulation data?','A registered scoping review screens 493 records and maps 27 studies by input type and clinical application.','Most models used derived assay parameters; raw-signal prediction was rare and external/calibration evidence limited.','Sub-minute and 20-second predictions remain hypotheses, not demonstrated capabilities.')
A('03307-9','Can multi-species malaria microscopy run rapidly and offline?','PlasmoCount 2.0 replaces Faster R-CNN with YOLOv8, adds batch inference and trains across species and smear preparations.','Processing bottlenecks fell by 90%, with sub-three-second image analysis and improved generalization to unseen parasite species.','Laboratory counting and smartphone feasibility are not prospective clinical diagnostic validation in the field.')
A('03298-7','Can genetic risk prediction borrow information learned from imaging without requiring imaging at deployment?','G2DBridge learns imaging-derived intermediate phenotypes from ADNI and evaluates genetic-only transfer in ADSP.','It outperformed reported polygenic-risk comparators for Alzheimer discrimination and highlighted pathology-consistent imaging regions.','External risk separation does not prove calibrated population screening or improved preventive decisions.')
A('03334-6','Can gaze photographs support both home strabismus screening and community-level subtype diagnosis?','A dual-stream, cross-attention network combines adaptive features from nine gaze directions.','Development used 84,897 photographs from 9,433 people; prospective testing used 10,458 photographs from 1,162 people, with subtype-dependent accuracy.','Photographs must not be counted as patients, and high diagnostic AUC does not establish improved referral outcomes.')
A('03297-8','Can prior and current surgical measurements identify hypoxemia risk before repeat lung resection?','Nineteen learners and feature-selection procedures yield a five-variable MARS model combining CT and clinical information.','Across 2,040 patients from seven hospitals, validation AUCs were approximately 0.75–0.78, outperforming pulmonary-function-only models.','Retrospective decision curves are not prospective evidence of safer anesthesia or prevented hypoxemia.')
A('03277-y','Do common AI evidence-search tools systematically miss clinically relevant literature?','Five platforms are tested across 15 query formulations against a prospectively assembled non-public reference corpus.','Single-query recall was limited; 12% of evidence was never retrieved, with particularly poor coverage of conference proceedings.','Pooled multi-query capacity must not be presented as the reliability of one routine clinical search.')
A('03257-2','Do CT vision-language representations retain population-level physiology and longitudinal risk information?','Percival contrastively aligns CT scans and reports, comparing embeddings with vision-only and segmentation-based approaches.','Training exceeded 400,000 CT-report pairs; over 20,000 held-out participants supported clinical associations and disease/risk analyses.','Imaging associations and retrospective predictions do not establish prospective utility or mechanistic causation.')
A('03241-w','Can surface-aware molecular representations generalize drug–target affinity prediction beyond familiar scaffolds?','SMCL-DTA combines topology-preserving masking, regression-aware contrastive pairs and molecular/protein surface features.','Six benchmark datasets supported warm- and cold-start evaluation; SOAT1 virtual screening received wet-lab follow-up.','Benchmark generalization and initial bioactivity do not establish drug efficacy, selectivity or clinical readiness.')
A('03236-7','Can constrained generation automate patient-specific dental crowns without sacrificing clinical acceptability?','A multi-view diffusion model jointly controls crown geometry and texture using morphological and functional constraints.','Blinded scores were comparable to experts, geometric error improved against baselines, and a supervised workflow reduced active design time by over 90%.','Proof-of-concept manufacturing and expert ratings do not establish long-term fit, durability or patient outcomes.')
A('03137-9','Can platform-independent movement traces measure robotic surgical expertise?','A random forest learns fundamental 3D kinematic patterns with case-wise and leave-surgeon-out evaluation.','Expertise AUC was 0.892, with a small set of interpretable movement features and exploratory outcome associations.','Movement–blood-loss correlations are observational; cross-platform applicability requires actual independent testing.')
A('03282-1','Can locally hosted LLMs retrieve Finnish clinical facts accurately under strict offline operation?','Fourteen open models answer 1,664 expert-annotated questions from 183 breast-care patient records.','The best accuracy was 95.3%, yet clinically significant errors occurred in 2.9% and equivalent questions sometimes changed safety outcomes.','High aggregate accuracy does not remove the need for source attribution, workflow validation and oversight.')
A('03309-7','Does personalized LLM preparation improve preoperative prostate-cancer communication?','A room-randomized phase-II comparison gives locally generated answers before standard physician communication.','Among 268 patients and 3,507 questions, AI preparation reduced anxiety, clinician workload and communication time.','Room-based allocation is clustered; registration timing and analysis of within-room correlation require full-text checking.')
A('03295-w','Where can patient and cellular digital twins support drug evaluation?','A review connects hybrid mechanistic/data-driven models, multi-omics integration and personalized simulation across development stages.','The authors outline emerging uses and a staged roadmap rather than one validated universal twin.','Computational plausibility and proposed applications should not be mistaken for established regulatory acceptance or drug-development benefit.')

A('03283-0','Can routine pediatric measurements identify elevated liver stiffness without specialized screening?','A seven-variable nearest-neighbor score is developed and evaluated in Chinese and US cohorts.','Training/validation samples were 437, 730 and 600; AUCs were 0.82, 0.87 and 0.80.','Liver-stiffness screening does not directly establish biopsy-confirmed fibrosis or improved clinical outcomes.')
A('03276-z','Do realistic generated surgical videos preserve correct operative logic?','SurgVeo combines expert assessment with a hierarchical plausibility framework to compare Veo-3 and Wan2.2.','Surgical-logic failures predominated despite visually convincing videos.','Visual realism is not procedural correctness, and benchmark plausibility does not validate use for surgical training or planning.')
A('03258-1','Can a simpler heart-failure predictor improve routine mortality stratification?','SIMPLE-HF is developed in CPRD records and compared with an EHR-adapted MAGGIC score.','Among 373,389 adults, twelve-month mortality C-index was 0.801 versus 0.735, with favorable calibration.','External and prospective evaluation remain necessary before clinical adoption.')
A('03279-w','What distinguishes AI-mediated communication from conventional provider–patient interaction?','A 67-study scoping review applies concept-analysis methods to attributes, prerequisites and consequences.','The framework combines personalization, clarification and simulated empathy with oversight and irreducible error risk.','The conceptual synthesis does not establish that these proposed communication benefits occur reliably in every deployment.')
A('03250-9','Can MRI automatically quantify and visualize acute cervical cord injuries while exposing uncertainty?','An uncertainty-aware segmentation pipeline is compared with seven-rater consensus and neurological measurements.','A 711-scan multicenter dataset supported overall lesion Dice of 70.44%; imaging features correlated with impairment.','Imaging–impairment associations do not establish treatment selection benefit or causal recovery prediction.')
A('03248-3','Can LLM judges substitute for clinicians when evaluating clinical answer quality?','Multiple judges, repeat runs and panels assess 118 protocol-based queries answered by deployed retrieval-augmented decision support.','Additional runs or judge panels did not consistently outperform the strongest single judge; pass/fail analysis exposed hidden disagreements.','Ordinal agreement can conceal clinically consequential errors, so automated judging requires task-specific human validation.')
A('03104-4','Can open ophthalmic language models combine specialty knowledge with stronger clinical reasoning?','LEME uses instruction tuning on 211,149 examples and preference learning on 29,747 examples.','It improved benchmark answers and visual-acuity extraction, while plan ratings approached attending assessments.','Benchmark and clinician ratings are not prospective evidence of safe autonomous treatment planning.')
A('03294-x','Can junior clinicians reliably catch hallucinations in plausible AI recommendations?','A multicenter simulated-decision study classifies GPT-4o errors and measures clinician detection across risk categories.','Only 15.8% of hallucinations were detected, without better detection for higher-risk situations.','Simulation identifies oversight vulnerability but does not directly measure patient harm or effectiveness of proposed safeguards.')
A('03293-y','Can uncertainty scores expose skin-image distribution shifts before deployment?','SAGE supervised autoencoders compare incoming images with HAM10000 and filter unreliable inputs.','Across five datasets from seven countries, scores identified artifacts and filtering improved a separate malignancy classifier.','Filtering changes the evaluated population; better retained-case performance does not establish safe handling of rejected patients.')
A('03287-w','Can offline causal reinforcement learning propose lower-intensity cognitive interventions?','A treatment-effect learner is combined with conservative Q-learning for continuous-action MCI strategies.','Model-estimated improvement averaged 1.03 Memory Guard points with lower recommended weekly intensity.','These are exploratory policy estimates rather than outcomes from randomized delivery of the learned policy.')
A('03300-2','How should diabetes self-management be defined when digital tools reshape patient roles?','Rodgers concept analysis combines manual synthesis with sentence-embedding clustering across 97 studies.','The resulting attributes span routines, cognition, support, personalization and evolving patient–provider relationships.','Conceptual consequences summarize the literature; they are not pooled intervention effect estimates.')
A('03269-y','Can interpretable image semantics support molecular typing of non-enhancing diffuse glioma?','A visual-language pipeline extracts imaging features and applies rule-aware molecular reasoning from CT/MRI.','Reported IDH and codeletion AUCs were 0.935 and 0.913; a 300-case reader experiment showed faster, more accurate decisions.','Reader gains are not randomized patient outcomes, and molecular prediction requires external clinical confirmation.')
A('03264-3','Can tissue-cell spatial organization improve postoperative lung-adenocarcinoma prognosis?','PathRosetta learns multiscale tumor ecology from routine slides and compares predictions across institutional and public cohorts.','In 430 patients and 876 slides, internal AUC was 0.78; external cohorts yielded approximately 0.75–0.76.','Prognostic associations and inferred cell subgroups do not establish molecular mechanisms or benefit from changed treatment.')
A('03280-3','Can retrieving similar patients improve LLM outcome prediction for less-common cancers?','Dynamic few-shot prompts combine semantic patient retrieval with clinical-note summaries.','Testing in 503 breast-cancer and 475 glioma patients produced larger improvements for glioma and modest breast-cancer gains.','The rarity hypothesis rests on two cancer groups within one cohort and needs broader institutional/tumor validation.')
A('03278-x','Can organizational change support routine use of a multi-vendor radiology AI platform?','A neuroradiology implementation combines orchestration infrastructure, education, standardized documentation and feedback.','The post-implementation platform processed 9,480 tasks across twelve applications, with increased but uneven adoption.','The bundled observational strategy cannot separate infrastructure effects from change management or establish patient benefit.')
A('03260-7','Can autonomous robotic scanning support thyroid-nodule screening with expert-assisted AI interpretation?','FARUSS scanning and Aitrox assessment are compared sequentially with conventional ultrasound in 262 people across three institutions.','Agreement was favorable, but scanning took longer and the screening strategy missed 19.2% of biopsy recommendations.','Exploratory image-quality triage does not remove the need for sonologist oversight or establish outcome safety.')
A('03244-7','Can longitudinal clinical data improve tacrolimus concentration estimates for personalized dosing?','DoseTailor uses an interpretable LSTM trained on fourteen years of data from 1,774 Spanish and US patients.','Concentration MAE was below 2 ng/mL and outperformed reported baselines.','Concentration prediction and a clinician-facing website do not prove improved therapeutic control or fewer adverse events.')
A('03237-6','Can shared representations reconstruct missing brain-connectivity modalities and predict traits?','BrainCSD uses consistency-driven mixtures of experts for connectome synthesis and multitask inference.','Evaluation covered 7,248 people, 22 sites, nine datasets and fifteen tasks.','Most validation was within datasets; larger prospective external testing and uncertainty calibration remain necessary.')
A('03255-4','Does infectious-disease AI research activity align with global disease burden?','Bibliometrics and GPT-4o-mini-assisted extraction analyze 9,026 publications with spatial comparisons.','Research concentrated around US/Chinese capacity and socioeconomic resources rather than disease burden.','Publication geography and modeled associations do not establish why research priorities arise or the effectiveness of represented AI tools.')
A('03205-0','Are chest-radiograph foundation-model papers reported well enough for clinical assessment?','A systematic review evaluates 41 models for CLAIM reporting, artifacts and physician co-authorship.','Sharing was limited; physician participation correlated with stronger reporting and more fairness discussion.','Co-authorship associations are observational and do not prove that physician inclusion causes higher research quality.')
A('03270-5','Can stigmatizing wording change AI triage against patients who subsequently deteriorate?','Three open models compare outcome-matched ED case pairs after neutral or stigmatizing attributes are inserted.','Across 221,556 comparisons, frequent-use stigma consistently produced harmful reprioritization, sometimes exceeding nine percent.','Controlled text manipulations measure model behavior, not actual triage decisions or observed treatment harms.')
A('03209-w','Can synthetic ultrasound images be accepted as real when readers are unaware of their presence?','A staged reader study separates purpose-blinded acceptance, explicit provenance detection and cue-supported workflow responses.','Only three of twelve readers spontaneously questioned provenance; explicit detection accuracy was 70.8%.','Perceived quality does not establish diagnostic fidelity, and later cue-supported phases do not prove intervention efficacy.')
A('02961-3','Does colposcopy AI transfer to an independent public image collection and help less-experienced readers?','A WHO dataset supports standalone model evaluation and assisted interpretation by 45 clinicians.','The 187-patient, 855-image evaluation showed reader sensitivity increasing from 84.8% to 90.6%, especially among less-experienced clinicians.','External reader performance does not itself establish effects on biopsy management or patient outcomes.')
A('03249-2','Can frozen video representations support objective laparoscopic certification scoring?','VideoPrism, V-JEPA2 and VideoMAE features feed lightweight heads with participant-held-out evaluation on two FLS tasks.','Best pass/fail AUCs were 0.907 for suturing and 0.991 for cutting; video encoders generally exceeded frame-based features.','Standardized task performance may not transfer to varied operative procedures or independent clinical credentialing.')
A('03247-4','How can clinicians recognize when an individual risk estimate lies outside familiar training examples?','PGower converts mixed-feature distance from training patients into an interpretable relative-similarity percentile.','Simulation links low similarity with model uncertainty; an ovarian-cancer example includes 9,108 cases.','Similarity is not a calibrated confidence interval or a guarantee of accurate prediction for a particular patient.')

A('03226-9','Can synthetic blood spectra preserve personal biology while varying age, sex or body mass?','Conditional autoencoder, GAN and diffusion generators learn 25,308 spectra from 5,863 participants.','Generated spectra supported individualized aging simulations and augmentation of underrepresented BMI groups.','In-silico phenotypes in ostensibly healthy volunteers do not establish disease-screening validity.')
A('03193-1','Can uncertainty-aware fusion improve predictions when molecular text and protein structures are noisy?','PML-DTI combines pocket-guided features, bidirectional Mamba processing and directional probabilistic embeddings.','Reliability-aware fusion exceeded seven reported comparators in within- and cross-domain benchmarks.','Computational interaction prediction is not experimental binding confirmation or drug efficacy.')
A('03253-6','Does training with clinically reconstructed CT pairs improve thin-slice synthesis?','MSS-CT provides 500 three-to-one-millimeter and 1,500 five-to-one-millimeter pairs; BasicCSS provides a reference network.','Real-paired training outperformed pseudo-paired simulations across evaluated methods.','Generated slices are auxiliary reconstructions, not recovered original acquisition information or validated clinical outcomes.')
A('03224-x','Can ontology knowledge improve multilingual normalization of biomedical terms?','Eight dense-retrieval models and six generative rerankers are tested with UMLS enrichment.','Best retrieval recall-at-one was 0.57; enriched reranking improved results but retained wording and ordering sensitivities.','Benchmark retrieval does not establish fully reliable clinical coding across languages or institutions.')
A('03090-7','Can controlled LLM comparisons probe sex-related asymmetries in recorded triage decisions?','Fine-tuned Mistral models predict triage and generate paired presentations in French and US records.','Female versions received lower-severity predictions more often, with asymmetries of 1.1% and 2.2%.','These are model probes of documentation, not proof of clinician discrimination or clinically meaningful undertriage.')
A('03207-y','Can pathology segmentation make pancreatic tumor lymphocyte–stroma measurements scalable?','A vision transformer classifies slide tissue and computes lymphocyte-to-stroma ratios across centers.','Higher ratios were associated with better survival in development and multicenter cohorts.','Prognostic correlation does not establish treatment sensitivity or benefit from ratio-guided management.')
A('03122-2','How reliably do pathology foundation models retrieve diagnostically similar slides?','Ten pipelines are compared on 9,387 TCGA slides using patient-held-out, within-organ retrieval.','Differences across organs and diagnoses exceeded many architecture differences; rare or similar subtypes remained difficult.','Within-TCGA benchmarking and supervised in-distribution references do not establish external clinical retrieval accuracy.')
A('03254-5','Can integrated molecular networks uncover rapid progression within nominally lower-risk prostate cancer?','Patient-specific multi-omics networks feed graph-weighted feature selection and LASSO-Cox prognosis.','Analysis of 498 TCGA cases implicated ZNF268 methylation and a risk-specific oncogenic transition.','Exploratory marker discovery requires independent biological and prognostic validation; mechanistic causality is not established.')
A('03246-5','Are AI-enabled medication wearables ready for routine adherence management?','A scoping review maps sensing applications, predictive performance and translational evidence.','Most studies concerned development or internal testing, with favorable controlled-setting results.','External validity, real-world effectiveness, clinical outcomes and routine-care integration remain weakly evidenced.')
A('03239-4','Do previously developed bacteremia models retain accuracy in prospective ICU evaluation?','Prospective prediction is compared with clinical scores and explored by culture timing.','Overall discrimination was modest; a post-hoc ICU-day-four-to-ten subgroup reached roughly 0.70 AUROC.','Post-hoc selection can improve apparent performance and requires prespecified independent confirmation.')
A('03204-1','Can ECG networks distinguish myocardial-infarction subtypes in clinically suspected cases?','A model pretrained on 173,396 patients is adapted and evaluated in two adjudicated prospective cohorts.','NSTEMI AUROC was 0.81, with weaker type-two discrimination; STEMI recognition exceeded the compared physician interpretation.','Performance varies by subtype, age and prior disease; diagnostic accuracy does not establish treatment benefit.')
A('03196-y','Can a standardized benchmark reveal generalizable ECG-model capabilities?','BenchECG combines eight datasets and ten tasks; xECG joins xLSTM with self-supervised representation learning.','The resource includes 421,171 patients and 1,674,704 recordings; xECG led the reported composite ranking.','Composite scores and repeated recordings must not be mistaken for independent prospective clinical evidence.')
A('03238-5','Can routine lymphoma slides predict rearrangements normally assessed with FISH?','HE2FISH uses weak supervision, with optional clinicopathological features, across paired slide/FISH cohorts.','Among 1,377 patients from five hospitals, mean external single-gene AUC exceeded 0.81.','Prediction is not equivalent to molecular confirmation; attention maps show associations rather than causal morphology.')
A('03203-2','Can heterogeneous tumor habitats improve thyroid-cancer nodal-metastasis prediction?','Thy-CLNM Fusion combines deep features with habitat-radiomics representations.','Validation AUC was 0.862, with sensitivity 78.9% and specificity 79.3%.','Reported discrimination does not demonstrate safer surgical selection or independent prospective clinical benefit.')
A('03199-9','Can a human-supervised generative-AI exposure session reduce academic anxiety?','Two randomized comparisons test a hybrid exposure program against active and waitlist controls.','Across 425 participants, immediate and two-week primary outcomes improved, with smaller effects against active controls.','Follow-up was short, broader symptom effects limited, and trial registration timing differed between studies.')
A('03228-7','How do patients experience LLM-supported education in clinical settings?','A mixed-methods systematic review synthesizes usage, perspectives and patient-reported outcomes.','Patients often valued accessible explanations but raised accuracy, privacy, trust and personalization concerns.','Perceived usefulness is not consistent evidence of sustained clinical benefit or a replacement for clinician communication.')
A('03070-x','Can smaller local agents extract rare-disease evidence without task-specific fine-tuning?','RDMA equips quantized LLMs with abbreviation, phenotype-reasoning and ontology-grounding tools.','It exceeded reported fine-tuned/RAG baselines while reducing inference and hardware costs.','Benchmark and cost gains require clinical workflow validation; local hosting alone does not guarantee correct phenotyping.')
A('03235-8','Can preoperative brain MRI predict response to pallidal stimulation for dystonia?','DystoniaDBSNet learns MRI-derived response markers with development, test and external cohorts.','The 175-patient dataset included 104 development, 30 test and 41 external cases; reported overall accuracy was 95.5%.','Small external samples and a referral/abstention mechanism limit extrapolation to unselected surgical candidates.')
A('03229-6','Can curated evidence and retrieval improve nursing-specific language-model support?','EviNurse adapts an LLM using NursData, organized around an evidence hierarchy, with benchmark and expert assessment.','Multiple-choice accuracy was 91.45%; experts favored reliability and satisfaction over general-purpose models.','Knowledge benchmarks and expert ratings do not establish bedside safety or improved nursing outcomes.')
A('03194-0','Can reproducible recurrence maps improve glioblastoma radiotherapy target coverage?','PREDICT-GBM benchmarks U-Net and biophysical models using longitudinal data from 243 patients.','Under equal-volume comparisons, modeled plans modestly increased coverage of subsequent recurrence.','Retrospective geometric coverage is not demonstrated survival gain, acceptable toxicity or a prospectively validated planning strategy.')
A('03111-5','Does LLM access improve physicians’ performance across different economic settings?','A parallel randomized experiment compares assisted and unassisted physicians in three countries.','Controlled-task gains were largest in Kenya, followed by Indonesia and the Netherlands.','Physician randomization is not a patient-outcome trial; results derive from controlled assessments rather than routine care.')
A('03223-y','Can a learned model identify arrhythmogenic sites without repeated patient-specific atrial simulation?','InduceNet learns nonpulmonary-vein triggers from personalized digital-twin pacing experiments.','Comprehensive pacing found more potential triggers, and the learned surrogate achieved 91% sensitivity.','Simulation-derived inducibility is not proof that targeting these sites improves ablation outcomes.')
A('03201-4','Can ordinary carotid ultrasound support plaque-risk assessment and longitudinal event stratification?','A cascaded multitask network detects plaques, characterizes features and classifies vulnerability.','External vulnerability AUC was 0.88; among 2,174 prognostic participants, AI risk added discrimination beyond clinical variables.','Observational event associations and decision curves do not establish benefit from AI-guided prevention.')
A('03202-3','Can peritumoral MRI improve recurrence stratification after meningioma radiotherapy?','Clinical variables are fused with deep MRI features and compared with radiomics across centers.','Deep features transferred more stably than radiomics; the fusion model averaged C-index 0.856.','Retrospective risk groups do not establish optimal treatment changes or causal benefit from model use.')
A('03198-w','Can topic-specific modeling reduce inequity in suicidal-ideation classification?','Clinical transcripts are factorized into simpler topics before classifier evaluation across alexithymia subgroups.','Topic-specific approaches reduced AUC disparities relative to a general classifier.','Reduced subgroup disparity does not establish safe crisis detection, and linguistic heterogeneity remains a deployment concern.')
A('03177-1','Can placental vessel organization yield interpretable unsupervised disease markers?','ODMMT combines optical-density masking, normalizing-flow scores and morphology-based clustering of trophoblast/red-cell relationships.','Two clusters separated healthy and diseased vessels and supported correction of classification errors.','Experimental image clustering is not validated prediction of recurrent preeclampsia or improved maternal outcomes.')
A('03189-x','How do infectious-disease surveillance platforms differ in their public-health roles?','A review compares twenty AI-enabled platforms by inputs, methods, privacy, pathogens and geographic scope.','Three archetypes emerged: early warning, situational awareness and integrated surveillance.','Platform taxonomy and reported capabilities do not establish comparative outbreak-detection accuracy or health-system impact.')
A('03191-3','Do medical vision-language models perform clinical reasoning beyond multiple-choice recognition?','The B&J benchmark compares fourteen vision-language and six language models on 1,245 musculoskeletal questions.','Accuracy exceeded 90% on structured questions but fell toward 60% on open multimodal tasks.','Text-driven hallucinations and case-format sensitivity limit claims of independent clinical competence.')
A('03185-1','Do AI-drafted patient replies reproduce demographic differences in communication tone?','Retrospective analysis compares 12,202 patient/draft/care-team message triads from three practices.','Drafts showed lower positive affect for several underserved groups; some analogous differences occurred in human replies.','Tone labels and demographic associations do not establish patient experience, discriminatory intent or resulting clinical harm.')
A('03175-3','Can an explicit reasoning model explain cardiac-MRI diagnoses from structured findings?','CMR-R learns diagnostic chains from quantitative parameters and report semantics using staged adaptive training.','Across 16,104 cases, reported accuracy was 0.858 and AUC 0.944 across eight categories.','Reader comparisons and retrospective reasoning quality do not establish prospective safety or improved management.')

A('03155-7','Which evidence stages should connect medical-model development to demonstrated clinical benefit?','A conceptual lifecycle framework specifies technical, operational, human-interaction, clinical and real-world evaluation phases.','It links external testing, shadow deployment, cooperation studies and trials with gating/fallback criteria.','This proposed framework is not an empirically validated guarantee of effective or safe deployment.')
A('03186-0','Can PubMed-grounded retrieval preserve evidence recall across languages?','PubChat uses E-utilities retrieval and relevance stratification against twenty Cochrane reviews and eight languages.','Broad retrieval favored recall/ranking, while the core configuration favored precision-weighted balance.','Benchmark performance depends on review domains and query configurations; it does not establish complete evidence capture.')
A('03018-1','Why have medication-adherence predictors struggled to reach clinical readiness?','A 41-study systematic review applies PROBAST+AI to development and evaluation methods.','Most models raised development-quality concerns, and 80% had high evaluation bias; complexity did not consistently improve discrimination.','Reported performance cannot overcome weak outcomes, missing-data handling and limited validation.')
A('03174-4','Can retinal images reveal clinically relevant obesity subtypes?','ROSA distills biomarker/retinal multimodal subtype information into a fundus-only predictor.','Across 63,693 participants, external macro-AUC fell to 0.66; sensitivity for one inflammatory subtype was only 0.02.','Poor minority-subtype sensitivity precludes treating favorable aggregate metrics as reliable comprehensive screening.')
A('03173-5','Can cortical recordings reconstruct useful deep-brain biomarkers when direct sensing fails?','Spectral processing and diffusion models learn simultaneous cortical/subcortical signals.','Evaluation covered 723 hours from 49 patients; reconstructed features tracked symptoms and supported state-detection rescue experiments.','Reconstruction above chance is not equivalence to implanted sensing or proven efficacy of closed-loop treatment.')
A('03161-9','Can text instructions control generation of three-dimensional candidate molecules?','TDmol aligns textual and 3D representations within an equivariant diffusion framework.','Experiments improved valid molecular generation under specified conditions.','Computational validity and prompt control do not establish synthesis feasibility, binding affinity or therapeutic efficacy.')
A('03121-3','Can CT anatomy improve prediction of conversion to arthroplasty after hip-fracture fixation?','MMHIP fuses preoperative pelvic CT and EHR variables across seven centers.','Development/external cohorts numbered 951/240; external AUC was 0.873 with high specificity at the fixed threshold.','Retrospective conversion-risk discrimination does not establish which initial operation improves patient outcomes.')
A('03168-2','Do sepsis machine-learning models outperform conventional prediction scores?','A systematic review and network meta-analysis pools diagnostic discrimination and explores model-related heterogeneity.','Best-model pooled AUC was 0.88, exceeding traditional comparators on average.','Model selection and heterogeneous validation limit interpretation; improved real-world patient outcomes remain unproven.')
A('03146-8','How does digital-therapeutic innovation differ by national economic context?','LLM-assisted classification, network analysis and diffusion modeling examine 1,672 patents and 7,439 registered trials.','High-income settings covered more therapeutic/technical areas, while lower-income settings concentrated on established technologies.','Patents and trial registrations are distinct units and do not demonstrate adoption, access or clinical effectiveness.')
A('03082-7','How do foundation models compare with student performance on medical licensing exams?','Models answer 7,485 items from twenty-four German examinations with historical student response references.','Frontier models approached ceiling accuracy, and several smaller/open models exceeded average student performance.','Exam performance does not establish clinical competence; benchmark timing and possible training exposure need consideration.')
A('03145-9','Can complementary blood and marrow morphology support broad hematological diagnosis?','Hierarchical multimodal learning fuses marrow/peripheral-smear features with recent chemotherapy status.','Almost 50,000 slides, including 17,000 paired specimens, supported eight-class discrimination with reported AUC above 0.90.','Slides, paired specimens and patients are different units; retrospective classification does not establish autonomous diagnostic safety.')
A('03144-w','Can pretrained agents improve breast-ultrasound assessment without task-specific fine-tuning?','AgentDS-BUS separates lesion segmentation, BI-RADS evidence extraction and structured decision aggregation.','Across 4,331 images, consensus-gated localization improved AUC, while ground-truth lesion masks produced larger gains.','Oracle masks are unavailable in normal use and must not be confused with deployable performance.')
A('03179-z','Can a local LLM build a structured kidney-cancer research database from clinical notes?','An open-model extraction pipeline maps operative, pathology and radiology documentation to fourteen variables.','For 8,366 patients and 130,509 notes, agreement with manual abstraction was 97.5%.','Reference-database disagreement adjudication supports extraction accuracy, not universal chart-review replacement or prospective clinical safety.')
A('03181-5','Can interpretable tissue segmentation yield transferable multi-cancer microenvironment biomarkers?','A fifteen-region pathology atlas generates spatial descriptors from tumor interiors and margins.','Up to 3,168 descriptors were associated with prognosis and molecular/immune phenotypes across nine cancers.','Associations across research cohorts do not establish causal biology or validated treatment-selection utility.')
A('03170-8','Can graph-guided retrieval make smaller local LLMs effective for oncology phenotyping?','OncoRAG combines ontology enrichment, knowledge graphs and reranking without weight fine-tuning.','Across breast, glioma and limited MIMIC cohorts, F1 was 0.80, 0.79 and 0.84, exceeding direct prompting.','Cross-cohort configuration and limited feature overlap constrain claims of unrestricted transfer.')
A('03178-0','Does a computable metabolic–adiposity measure retain stroke associations across population surveys?','Adjusted association analyses and exploratory ML transfer compare METS-VF across NHANES, CHARLS and ELSA.','Stroke associations replicated, but incremental prediction was dataset-dependent and cross-cohort transfer limited.','Self-reported stroke and observational analyses do not establish adjudicated prospective clinical prediction.')
A('03171-7','Can multimodal integration produce reproducible sepsis subgroups across countries?','MINERS combines discovery, transfer and validation modules for patient clustering and early subtype assignment.','Data from 55,940 patients yielded subtypes with differing trajectories, prognosis and treatment-response associations.','Observed treatment associations do not establish that subtype-guided therapy improves outcomes.')
A('03169-1','Does multiple-choice performance overstate neuroradiology models’ open diagnostic capability?','Multimodal models generate diagnoses and then select among options, with neurosurgical grading of errors.','Open accuracy was 51.6–62.7%, rising to 75.4–81.0% with options; clinically significant errors remained frequent.','These controlled comparisons do not support autonomous use or prove safe physician-assistive deployment.')
A('03165-5','How asymmetric are European and US authorization sequences for radiology AI?','A regulatory-cohort analysis uses time-to-event models for 239 CE-marked or FDA-cleared devices.','CE-first dual-authorized products had median second-authorization delay of 17.5 months versus 3.5 for FDA-first products.','Authorization dates do not measure clinical quality, evidentiary rigor or reasons for manufacturers’ market sequencing.')
A('03167-3','Do reasoning-focused models better address complex nasopharyngeal-cancer management questions?','Open-ended answers from reasoning and general language models receive multidimensional clinical scoring.','Reasoning models generally scored better, with differences across accuracy, relevance and completeness.','Expert-scored answers do not establish reliable case-specific treatment recommendations or clinical outcome benefit.')
A('03123-1','Can routine metabolic and inflammatory measurements detect cachexia without recalled weight history?','An interpretable model learns a biologically informed feature panel in the INSCOC cancer cohort.','Among 16,858 patients, test/validation AUCs were 0.758/0.748, with temporal evaluation.','Phenotype discrimination is moderate and does not establish causal cachexia mechanisms or improved supportive care.')
A('03114-2','Can continuously updated EHR risk trajectories quantify illness severity in older ICU patients?','Elder-DDB uses interpretable temporal deep learning across international critical-care cohorts.','Training included 41,050 admissions and external testing 47,335; external AUCs ranged from 0.801 to 0.834.','Admissions are not necessarily unique people, and dynamic mortality prediction is not proven benefit from acting on alerts.')
A('03095-2','Why do EHR risk models for treatment-resistant depression fail across systems?','Transparent L1-regularized predictors are trained and externally tested in three healthcare systems.','Transport performance was poor, with outcome heterogeneity, source-data bias and practice variation identified as failure mechanisms.','The study diagnoses limitations of recorded-data prediction rather than validating an actionable clinical risk tool.')
A('03078-3','When are AI diabetic-eye screening pathways economically preferable for health systems?','A five-year Markov model compares AI, teleophthalmology and professional examination across volume/payment scenarios.','Preferred strategies changed with patient volume and willingness to pay; AI benefited from immediate feedback assumptions.','Projected screening/treatment gains are model outputs, not observed trial effects or universally transferable cost thresholds.')
A('03054-x','What mental-health harms are hypothesized or observed with general LLM chatbots?','A scoping review synthesizes 119 of 3,137 identified articles across conceptual, vignette and empirical categories.','Themes include unsafe responses, overreliance, problematic dependency and possible reinforcement of delusional beliefs.','Evidence types differ substantially; associations and proposed mechanisms must not be presented as established causal incidence.')
A('03151-x','Can an integrated OCT system automate quality control through retinal diagnosis?','FOCUS combines an image-quality network with a fine-tuned visual foundation model.','Training/testing covered 3,300 patients; external evaluation included 1,345 patients, with high but site-varying diagnostic F1.','Slices are repeated measurements, and accuracy/reader comparisons do not establish safe unsupervised screening outcomes.')
A('03148-6','Can preoperative radiographs generate plausible postoperative scoliosis alignment?','SVV-Net conditions image generation on surgeon-selected fusion segments.','Generated alignment agreed with actual postoperative measurements and received favorable expert ratings.','Validation only covers the fusion plan actually performed; alternate-plan comparison remains untested.')
A('03117-z','How do LLMs summarize patients’ perceptions of physicians at national scale?','A validated extraction pipeline derives ten trait dimensions from online review text.','Analysis of 4.1 million reviews covering 226,999 physicians revealed demographic/specialty patterns and four perceived-trait clusters.','Review-derived traits are not objective physician competence, and platform selection and social bias remain important.')
A('03075-6','Can biomechanical geometric learning predict soft-tissue changes after jaw surgery?','PhysSFI-Net links skeletal changes with facial-surface deformation using physics-informed learning.','Training used 135 patients and external testing 33; external global-shape error averaged 1.431 mm.','Small-cohort shape accuracy does not establish superiority of treatment plans or patient satisfaction.')
A('03085-4','Can an ECG foundation model help identify coronary stenosis before CT imaging?','An adapted ECG model learns vessel-specific CCTA thresholds and combines predictions with pretest probability.','Reported internal/external discrimination and risk reclassification improved, including in normal-ECG cases.','Anatomical stenosis prediction is not direct physiological ischemia assessment or evidence of better clinical outcomes.')

A('03032-3','Can noncontrast MRI support interpretable liver-lesion classification across centers?','PRISM segments and classifies lesions, with retrospective cohorts, prospective recruitment and assisted radiologist assessment.','The 12,823-patient resource showed high binary accuracy and improved reader speed; prospective testing included 1,147 consecutive patients.','Binary and subtype performance differ, and reader improvements are distinct from patient-management outcomes.')
A('03153-9','Does a textbook retrieval layer add value to strong pediatric-cardiology models?','NadasGPT compares eight models with/without retrieval on 304 questions across training levels.','Recent models reached 98.4% unaided accuracy; retrieval rarely produced significant additional gains.','Near-ceiling multiple-choice performance cannot establish educational utility or reliability in real clinical questions.')
A('03150-y','Can noncontrast CT classify hepatic echinococcosis stages in resource-limited hospitals?','A two-stage network combines lesion segmentation, 2D/3D representations and radiomics, with reader assessment.','Development/internal cohorts included 733 patients and external cohorts 261; external macro-AUC was 0.931.','Adjacent transitional stages remained difficult, and retrospective reader gains do not establish treatment-selection safety.')
A('03140-0','Can explainable tabular models identify metabolite panels across liver-disease stages?','TabPFN-SHAP derives statistical co-contribution networks from 160 metabolites and integrates known biomarkers.','The study analyzed 1,312 participants and externally tested 721 samples, with high HCC-panel discrimination.','SHAP co-contribution is not a biochemical interaction network or proof of longitudinal disease mechanisms.')
A('03097-0','Can agents reuse analytical experience without violating EHR-specific methodological constraints?','HealthFlow governs prior workflows as structured planning experience and tests end-to-end artifact execution.','It exceeded reported agent baselines across EHRFlowBench and four additional benchmarks.','Executable benchmark artifacts do not establish correct conclusions on arbitrary new clinical datasets.')
A('02962-2','Can coordinated retrieval from several medical sources improve evidence-grounded answers?','MultiMed-RAG decomposes questions, selects knowledge sources and verifies evidence through specialized agents.','Across nine benchmarks it improved over direct generation and existing retrieval baselines.','Benchmark gains and source attribution do not guarantee source correctness or safe patient-specific recommendations.')
A('03147-7','Can virtual orthopedic experiments compare implants across realistic anatomical variation?','Validated finite-element simulations feed machine-learning analyses of fixation and remodeling risk.','A humeral-stem case study compares two designs across more than 500 simulated surgeries.','Virtual surgeries are not enrolled patients, and simulator validation does not substitute for comparative clinical outcomes.')
A('03118-y','Can uncertainty-aware models recognize unfamiliar or ambiguous infant fundus findings?','An open-set system scores uncertainty and routes uncertain cases for expert review.','External AUCs were 0.969–0.982; excluding uncertain predictions increased retained-case accuracy.','Selective abstention changes coverage, so retained-case performance must be reported alongside referrals and missed cases.')
A('03100-8','Can audio-only edge processing provide fast structured clinical-skills feedback?','CliniSense links transcription, speaker/role recognition, competency classification and conversation scoring.','On 270 simulated consultations, agreement exceeded mean annotator agreement with sub-1.5-second streaming latency.','Prospective validation was described as ongoing; simulations do not establish validity in real resident encounters.')
A('03064-9','Can parameter-efficient federated adaptation improve clinical extraction without sharing raw records?','Fed-MedLoRA aggregates local adapters with heterogeneity-aware methods and an optional perturbed-update variant.','Five cohorts containing 42,198 entities and 41,570 relations showed improved extraction and new-site adaptation.','Federation alone is not a privacy guarantee, and extracted entities are not independent patients.')
A('03143-x','Can individualized treatment-effect estimates guide rheumatoid-arthritis drug choice while enforcing safety rules?','Causal forests with double machine learning combine registry evidence and guideline constraints.','Across 4,885 treatment courses, concordant therapy was associated with higher response after adjustment.','Observational concordance and modeled treatment effects remain vulnerable to confounding and require prospective policy testing.')
A('03136-w','Can prompt refinement make clinical-letter extraction accurate without expensive model training?','A specialist-annotated ophthalmic pipeline iteratively refines prompts and maps efficiency/error trade-offs.','Diagnostic extraction reached micro-F1 0.954 and temporal-validation F1 0.945–0.980.','High extraction agreement does not establish clinical correctness beyond the selected conditions or source institution.')
A('03135-x','Can disease knowledge improve medically faithful image generation from reports?','UniMedDiff conditions diffusion on clinical text and prior disease information.','It improved reported generation metrics and supported downstream augmentation when little real training data was available.','Synthetic-image and classifier benchmarks do not prove clinical fidelity, privacy preservation or diagnostic safety.')
A('03134-y','How does individual reliance on AI affect difficult renal-pathology diagnosis?','A morphological aid is tested in a 21-pathologist, 30-case crossover study with reliance/overreliance measures.','Accuracy rose from 60.0% to 73.3% and inter-reader agreement improved.','Small challenging-case experiments support behavioral hypotheses, not patient-outcome or generalized expertise claims.')
A('03069-4','Do specialist personas change treatment decisions or mainly the language of tumor-board simulations?','Five GPT-5 role prompts and an ensemble address 100 gastrointestinal oncology cases.','MDT concordance ranged from 78% to 87% without significant framework differences; specialist language did not predict accuracy.','Simulated roles are not independent clinical experts, and concordance does not establish optimal treatment.')
A('03138-8','Can phenotypic similarity identify heterogeneous benefit from sacubitril/valsartan?','PARAGUIDE models individualized treatment effects using PARAGON-HF data and validates in another trial.','A 4,161-patient phenomap yielded a simplified sixteen-variable tool despite nonsignificant overall population benefit.','Reusing randomized-trial data is not a new randomized evaluation of the prediction-guided treatment policy.')
A('03132-0','When do clinicians, algorithms or their combinations best predict ICU outcomes?','Mixed retrospective/prospective comparisons evaluate individual expertise, clinician aggregates and hybrid predictions.','Performance depended on setting and professional experience; combined predictions often performed best.','Prediction comparisons do not show that a particular collaboration strategy improves actual treatment or survival.')
A('03130-2','Can routine ECGs screen hypertrophy and distinguish cardiomyopathy phenotypes?','An end-to-end network performs three hierarchical tasks across multicenter ECG data.','Training included 12,618 ECGs from 11,290 patients; external discrimination declined variably across tasks.','Subtype-specific external performance and repeated ECGs matter; screening does not replace diagnostic imaging.')
A('03125-z','How mature are NLP applications to psychosis EHR research?','A systematic review synthesizes 62 studies covering symptom extraction, trajectories and clinical prediction.','Many reports noted limited generalizability, and only two performed external validation.','Large aggregate study populations do not compensate for weak cross-system validation or establish clinical utility.')
A('03120-4','Can video-derived movement dynamics standardize Parkinson motor scoring?','TF-Mamba combines time/frequency representations with expert-consensus limb ratings.','Development included 1,479 patients and external testing 450; assistance improved junior-reader agreement and speed.','Agreement with consensus is not direct improvement in treatment decisions or disease outcomes.')
A('03109-z','How accurate are LLMs when ranking rare-disease diagnoses?','A meta-analysis synthesizes fifteen studies and nineteen system–dataset evaluations.','Pooled first-rank recall was 43.3%, with extreme heterogeneity; augmented systems performed better descriptively.','Overlapping cases, wide prediction intervals and subgroup confounding preclude a universal diagnostic accuracy claim.')
A('03077-4','What does early evidence show about OpenEvidence clinical answering?','A systematic review examines answer relevance, evidence attribution, hallucinations and decision support.','Studies often favored guideline-based responses, while complex-case performance varied and decisions were frequently reinforced rather than changed.','Early heterogeneous evaluations do not establish patient benefit or uniformly reliable clinical recommendations.')
A('03126-y','Is an AI skin-lesion app economically justified in Belgian diagnostic pathways?','Decision trees model SkinVision versus usual care for malignant and benign lesions.','Lower costs coincided with lower cancer detection and unnecessary benign referrals; the analysis did not support implementation.','The horizon ends at diagnosis, so conclusions depend on diagnostic assumptions rather than observed long-term outcomes.')
A('03103-5','Can language models recover detailed epilepsy phenotypes from notes?','Fine-tuned BERT and DeepSeek-R1 are compared with epileptologist agreement and applied at health-system scale.','Reasoning-model performance held up better on granular tasks; deployment covered 77,049 notes from 18,566 patients.','Research phenotyping performance does not establish prospective decision-support safety or replace specialist assessment.')
A('02946-2','Can automated sleep staging transfer to Parkinson and prodromal REM-behavior disorders?','U-Sleep is fine-tuned on multicenter polysomnography and evaluated on a held-out clinical cohort.','Held-out agreement improved from kappa 0.60 to 0.64; confidence thresholds increased REM precision.','Human disagreement remains substantial, and confidence filtering trades coverage against retained-recording reliability.')
A('03116-0','Can a monitoring agent identify risks during telemedicine conversations?','MedGuard combines memory-based claim extraction, adaptive retrieval and hierarchical risk classification.','Real/synthetic benchmarks and professional evaluations favored the system over reported agent baselines.','Benchmark improvements and evaluator judgments do not establish prevention of adverse events in live consultations.')
A('03115-1','Can learned epidemic–behavior coupling explain different responses across socioeconomic settings?','BC-PINN learns behavioral dynamics within a physics-informed epidemic model, followed by symbolic regression.','Across 58 countries it identified development-associated response patterns; counterfactual simulations reduced modeled infection peaks.','Country-level associations and simulated behavioral changes are not causal policy intervention evidence.')
A('03107-1','Can sequential question answering improve hierarchical gastric-slide diagnosis?','AUGUST organizes coarse-to-fine pathology decisions as linked questions with optional human interaction.','Evaluation used 23,072 slides and 79,924 question–answer pairs across nineteen tasks, improving reported consistency and accuracy.','Slides/questions are not independent patients, and benchmark gains do not establish autonomous clinical deployment safety.')
A('03133-z','Can general LLMs diagnose spinal disease from authentic radiology reports?','Four models process 20,277 reports across institutions, modalities and option/no-option conditions.','Overall specificity was high, but low-prevalence diseases suffered large precision losses.','Report-text interpretation is not direct image reading, and aggregate metrics conceal rare-disease failure.')
A('03110-6','Can posture and movement videos support fracture triage without immediate imaging?','A multimodal LLM extracts features for a second-stage boosting classifier.','Independent testing in 56 people yielded AUC 0.838; recalibration improved probability reliability without changing discrimination.','Small external samples and post-hoc calibration require independent confirmation before diagnostic use.')

A('03102-6','Can gastric-biopsy AI classify a broad diagnostic spectrum and assist pathologists?','GBAIM learns six slide-level classes with separate early-cancer and nodal-risk extensions.','Retrospective data included 17,086 patients; prospective recruitment added 2,965, with improved assisted-reader accuracy and speed.','Slide classification, invasion prediction and nodal prediction have different performance and must not be conflated.')
A('03086-3','Can adaptive mental-health policies optimize both when and what support is delivered?','Two-stage offline reinforcement learning uses a six-week micro-randomized dataset of 190 participants.','The learned rules target next-day composite symptom improvement and yield interpretable personalized recommendations.','The learned policy itself was not prospectively randomized; findings remain hypothesis-generating.')
A('03061-y','Can an OCT system combine disease recognition with clinically usable reports?','iOCT joins hierarchical annotations, data distillation and integrated diagnostic/natural-language reporting.','Prospective testing across ten hospitals included 8,998 cases; integrated reports received substantially higher physician-quality ratings than text alone.','Report ratings and diagnostic accuracy do not establish safe unsupervised deployment or improved patient outcomes.')
A('03060-z','What evidence supports multimodal foundation-model agents in healthcare?','A scoping review maps thirty-seven studies by modalities, tools, architectures and evaluation practices.','Architectures and capabilities varied, while safety, fairness and prospective outcome evidence were sparse.','Promising demonstrations should not be read as validated real-world clinical effectiveness.')
A('03087-2','Can generative feedback strengthen a short anxiety-focused worry-log intervention?','A three-arm trial compares personalized AI feedback, human feedback and unsupported worry logging.','AI feedback improved anxiety/worry versus logging alone, with acceptability and improvement comparable to human feedback.','A ten-day intervention does not establish durable benefit, crisis safety or equivalence across broader patient groups.')
A('03074-7','Can a scene-based injury estimate substitute for hospital anatomical scores in prehospital prediction?','PHISE is validated in US and multinational trauma registries and embedded in multivariable ML predictors.','Standalone mortality prediction lagged ISS/NISS, while transfusion prediction and combined-model performance were more comparable.','Score compatibility and registry validation do not establish prospective field usability or better triage outcomes.')
A('03092-5','Can sensor-driven wheelchairs improve independent mobility for intended users?','A review compares control interfaces, sensing, computing platforms and safety mechanisms.','Systems showed promising reductions in effort, but most validation involved healthy rather than mobility-impaired people.','Limited intended-user and long-term evidence constrains claims of safe daily-life autonomy.')
A('03081-8','Does access to AI-enabled between-session support add value to psychotherapy?','An observational comparison relates employer-level feature availability to engagement and symptom trajectories.','Access was associated with modest additional symptom improvement and higher reliable-improvement rates.','Nonrandomized access and engagement differences prevent causal attribution to the AI features.')
A('03079-2','Can capsule-endoscopy videos produce efficient, evidence-linked clinical reports?','CE Reporter combines multitask keyframes and time-aware vision-language alignment.','Clinician evaluation favored report completeness and speed, with performance varying across centers/devices.','The abstract contains an apparently inconsistent BLEU comparison; linguistic metrics and reviewer scores do not establish diagnostic safety.')
A('03033-2','Are digital-health trials reporting technology and participant characteristics needed to assess equity?','An LLM-assisted landscape analysis examines 5,452 registered randomized-trial outcomes.','Digital-health trial growth exceeded overall registration growth, motivating standardized access/equity reporting.','Registry descriptions and trial counts are not evidence of equitable enrollment, implementation or clinical effectiveness.')
A('03089-0','Can AI-assisted morphology improve routine blood-smear review?','A prospective randomized paired-method comparison evaluates automated assistance against manual microscopy.','Across 1,570 smears from three centers, selected abnormal-cell detection improved and technician efficiency increased by about 60%.','Randomization concerns review methods, not patient treatment; low absolute F1 for some morphologies remains important.')
A('03071-w','Can each antenatal visit update predicted delivery timing from routine records?','A longitudinal model learns retrospective singleton/twin histories and tests same-center temporal and external prospective cohorts.','Development covered 56,373 singleton and 3,577 twin pregnancies; prospective performance differed substantially between pregnancy types.','Prediction updates do not establish effective prevention, and twin external discrimination was weaker.')
A('03067-6','Can a local LLM route referrals to the appropriate available subspecialty?','Roster-aware Qwen processes 6,624 referral letters and is compared with coordinators and expert adjudication.','On 680 held-out letters, accuracy rose from 75.4% against coordinators to 84.7% after disagreement adjudication.','Adjudicated accuracy uses a revised reference and is not evidence of prospective workflow benefit.')
A('03009-2','Can one policy-optimized multimodal architecture support several prostate-cancer tasks?','A MedGemma framework is configured separately for imaging segmentation, grading and survival prediction.','The study explicitly separates task-specific datasets, modalities and comparator settings.','No fully matched MRI/ultrasound/pathology cohort supports treating every result as one universal patient-level validation.')
A('03084-5','Can synthetic-data distillation make automated clinical-text evaluation closer to physician judgment?','MedVAL trains evaluator models without physician training labels and tests 840 annotated outputs across six use cases.','Average factual-consistency F1 increased from 66% to 83%, including improvements in strong proprietary judges.','Agreement on a selected benchmark does not establish exhaustive detection of clinically consequential errors.')
A('03058-7','Can agents keep a medical knowledge graph current as literature changes?','MedKGent constructs time-aware entities/relations and evaluates graph-grounded retrieval.','Its graph contains 156,275 entities and approximately three million triples, improving downstream answers across several models.','Triple quantity and benchmark gains do not guarantee factual correctness, completeness or safe clinical recommendations.')
A('03063-w','How do engagement and preferences differ between automated and human-led diabetes prevention?','A phase-III trial compares fully automated AI coaching with a recognized human-coach program.','Among 368 adults, AI participants started sooner and engaged more evenly across twelve months.','Engagement and acceptability endpoints must be separated from weight-loss or diabetes-incidence outcomes reported elsewhere.')
A('03062-x','Can radiological semantics complement CT representations for lung-nodule invasiveness?','A multimodal network fuses 3D nodule patches with structured imaging descriptors.','Development included 2,004 patients; two external cohorts showed AUCs of 0.879 and 0.895.','Nodules are nested within patients, and subtype prediction does not establish optimal extent of surgery.')
A('03053-y','Which speech-derived metrics remain informative across languages in psychosis research?','Fifty-one NLP measures are evaluated in German and Russian speech datasets.','Simple verbosity measures often exceeded more complex features and remained robust across tasks/rating scales.','Cross-language robustness in two datasets does not establish universal diagnostic validity or language-independent thresholds.')
A('03030-5','Can vision-language training reduce intersectional diagnostic gaps without sensitive inputs at inference?','CMAC-MMD regularizes cross-modal certainty across demographic subgroups.','Skin-lesion and fundus benchmarks showed reduced true-positive-rate disparities with maintained or improved overall discrimination.','Statistical parity on selected datasets does not prove equitable clinical outcomes or eliminate distribution-shift risk.')
A('02997-5','Can EEG-informed digital-twin biomarkers predict later cognitive conversion?','DADD maps noninvasive neural recordings to latent neurodegeneration parameters and compares established biomarkers.','A 459-person cognitive-decline cohort showed prognostic value over ten-year follow-up, including gains when biomarkers were combined.','Longitudinal source follow-up is not prospective deployment validation or proof that inferred parameters reflect causal disease mechanisms.')
A('03080-9','Are chatbot suicide-risk evaluations appropriate for adolescents?','A focused review examines disclosure detection, response quality and gaps in youth-centered evidence.','Most studies used researcher-written single-turn prompts; indirect or gradual disclosure degraded performance.','Real-world effects on youth suicide risk remain unknown, so simulated response quality cannot establish safety.')
A('02842-9','How common is mental-health use of general-purpose LLMs, and among whom?','A demographically stratified US survey asks 1,871 adults about use, motivations and access barriers.','Twenty-four percent reported such use; population extrapolation suggested fourteen to eighteen million users in 2024.','Self-report sampling and external prevalence assumptions limit national estimates, and perceived support is not clinical efficacy.')
A('02933-7','Can a harmonized global trial resource improve specialized research-task models?','TrialPanorama links 1.6 million registrations with ontologies and trains an eight-billion-parameter model using supervised/reinforcement learning.','Across eight benchmark tasks, the adapted model exceeded larger generic models.','Trial records, training samples and independent trials are different units; benchmark gains do not validate actual trial-design decisions.')
A('03072-9','Can causal learning explore individualized radiation-toxicity relationships?','Dose-effect models analyze mandibular osteoradionecrosis in 931 head-and-neck radiotherapy patients.','The framework estimates heterogeneous dose-related effects rather than only conventional predictive associations.','Causal interpretation depends on observational assumptions and requires prospective validation before changing dose constraints.')
A('03068-5','Can smartphone speech aid depression assessment in adolescents?','A fine-tuned Whisper model is compared with interpretable acoustic features across multiple centers.','Development included 1,838 adolescents and external testing 145; external AUROC reached 0.88.','Clinician-defined case–control discrimination is not general-population screening performance or a replacement for clinical assessment.')
A('03066-7','Can coordinated imaging-grounded agents improve stroke-treatment recommendations?','A multidisciplinary-style multimodal agent pipeline combines structured coordination with retrieval augmentation.','In 1,658 retrospective suspected-stroke cases, recommendation accuracy rose from 0.636 to 0.785.','Agreement with recorded/reference decisions does not prove safer reperfusion treatment or better prospective outcomes.')
A('03057-8','Can structural and functional brain networks explain different pathways of tau spread?','A multilayer graph-diffusion framework learns coupling through physics-informed neural modeling and tests independent neuroimaging data.','The dominant modeled pathway shifted from functional to structural connectivity with disease stage.','Mechanistic-model fit and gene/risk-factor associations do not prove causal propagation routes or treatment targets.')
A('03045-y','Can LLMs detect incomplete trial outcomes and changes after registration?','An automated comparison parses prospective registrations and posted results on ClinicalTrials.gov.','It achieved high sensitivity/precision for incomplete definitions and identified most missing or added outcomes.','Detected registration discrepancies require adjudication and do not alone establish selective reporting or research misconduct.')
A('03022-5','How does the appearance of AI-mediated bad-news delivery affect stress and memory?','A Wizard-of-Oz simulation compares human consultations with human-controlled chatbot/avatar formats.','Among 163 healthy participants, human formats produced greater stress and chatbot-style encounters showed lower memory retrieval.','The experiment tests beliefs about AI, not actual AI clinical performance or communication with ill patients.')

A('03051-0','Can complete radiology findings guide spatial segmentation without short handcrafted prompts?','CF2Seg fuses report/image information during feature formation and decoding.','A 53,386-examination annotated benchmark supported robust segmentation and lesion-burden agreement under several perturbations.','Retrospective spatial annotation is not demonstrated benefit from real-time diagnostic deployment.')
A('03037-y','Can ultrasound AI improve fetal-abnormality recognition by interpreting physicians?','A retrospective multireader study evaluates Sonio Suspect on eight abnormal findings in still images.','Mean reader AUC increased from 68.9% to 90.9%, with improved sensitivity and preserved specificity.','Still-image reading does not evaluate acquisition quality, complete real-time scanning or fetal outcomes.')
A('03006-5','Can federated decision-support networks learn across facilities with nonmatching available features?','FedMoDN uses modular neural components rather than discarding or imputing incomplete feature/label sets.','Approximately 130,000 visits across 92 facilities supported external AUPRC 0.80 and resilience to missing features.','Visits are not unique patients, and missingness experiments do not establish safe prospective recommendations.')
A('02958-y','Can pathology federation operate across hospital security boundaries without opening firewall ports?','TheODen supports distributed segmentation training across heterogeneous institutional infrastructure.','Three German hospitals demonstrated colorectal/breast segmentation with Dice around 0.75–0.76.','Successful secure training infrastructure is not proof of privacy against every attack or clinical segmentation utility.')
A('03016-3','Can routine blood counts flag previously unrecognized leukemia?','LeukoAlert learns seventy-two CBC features across multicenter records and is checked prospectively.','Development/testing covered 203,284 people; a 58,481-record prospective evaluation achieved AUC 0.969.','Records may repeat people, and risk flagging does not replace confirmatory hematological diagnosis.')
A('03012-7','Can early coagulation signals safely reduce unnecessary lupus-anticoagulant testing?','MINI-LAC uses phospholipid-dependent parameters to identify likely-negative evaluations while preserving full testing for uncertain cases.','Across 7,454 evaluations, prospective negative predictive value was approximately 98%.','High negative predictive value depends on prevalence and does not justify omitting evaluation in uncertain or positive cases.')
A('02945-3','Can multimodal reasoning models transfer across unfamiliar clinical modalities and institutions?','QoQ-Med3 variants are assessed for task/modality transfer and cross-site robustness.','The reported overall balanced accuracy was 71.3%, but overall F1 was only 0.349.','Strong relative rankings do not overcome low absolute performance or establish reliable clinical deployment.')
A('03008-3','Can cardiovascular risk be estimated when imaging and clinical variables are incomplete?','MACE-MAIS combines multimodal representations with integrated reasoning across missing CMR/EHR inputs.','Across four datasets it exceeded compared baselines and produced clinically interpretable rationales.','Explanations and retrospective risk discrimination do not establish calibrated decisions or improved event prevention.')
A('02972-0','How do design choices shape users’ experience of purpose-built mental-health chatbots?','A 21-study scoping review maps interaction features, interventions and reported user experience.','Usability was often favorable, but engagement declined and inaccurate replies undermined trust.','Most systems were early-stage; satisfaction and therapeutic alliance do not establish clinical efficacy or safety.')
A('02928-4','Can open LLMs support structured interview-based psychosis-risk assessment?','Eleven models analyze 678 partial interviews from 373 participants.','The strongest model achieved accuracy 0.80 and sensitivity 0.93, but specificity was 0.58 and varied across sites.','An enriched high-risk cohort and low specificity limit general-population screening claims.')
A('02467-y','Can prompting improve automated interpretation of routine health-check measurements?','Several LLMs are compared across prompt strategies and individual laboratory/vital-sign items.','Accuracy improved substantially with structured reasoning, but blood-pressure interpretation remained weaker than simple biochemical thresholds.','Threshold classification is not comprehensive clinical interpretation, and complex semantics remain a safety concern.')
A('03026-1','What differs between developer evidence and user satisfaction in mental-health apps across countries?','LDA clusters reviews, with DeepSeek-assisted topic labeling and cross-national semantic integration.','Clinical-evidence disclosures and satisfaction priorities differed between China and the US; personalization was commonly insufficient.','Store reviews and developer claims are selected observational data, not measures of app efficacy.')
A('02964-0','Can passive sleep signals reveal departures from normal aging associated with dementia?','A sleep-age model learns longitudinal under-mattress sensor data and evaluates dementia discrimination.','The cohort contained 1,672 people and 18,369 person-samples; unseen-data sensitivity/specificity were approximately 76%/75%.','Repeated samples are not independent participants, and group discrimination does not prove early clinical diagnosis.')
A('03048-9','Can structured multimodal classification and retrieved evidence help diagnose cognitive impairment with missing data?','MEDRF joins a hierarchical classifier with retrieval-augmented correction.','External accuracy improved from 0.706 to 0.753, with larger correction effects under severe feature masking.','Artificial masking and retrospective labels do not establish safety when real-world missingness differs.')
A('03038-x','Can domain-grounded agents improve patient-facing atrial-fibrillation explanations?','PULSE augments four base models with specialist knowledge and evaluates seventy-five real patient questions.','Blinded experts rated factuality, utility, safety and readability more highly than unaugmented responses.','Expert-rated answers are not observed improvements in self-management, adherence or long-term outcomes.')
A('03035-0','Can hierarchical retrieval reduce unsafe diabetic-kidney-disease recommendations?','A local retrieval layer and cloud reasoning engine are grounded in guidelines and evaluated by twelve physicians.','In 267 retrospective cases the system improved concordance and reduced renal-stage medication errors.','Reference-guideline agreement is not prospective clinical safety, and hybrid deployment has separate governance requirements.')
A('03027-0','Can combined MRI, pathology and clinical variables estimate changing survival risk after liver-cancer surgery?','TEMPO-HCC uses an interpretable multimodal survival architecture.','The six-center cohort contained 1,475 patients; external C-index was 0.751 with horizon-dependent AUCs.','Discrimination declines at some time horizons, and postoperative prediction is not evidence of improved risk-adapted care.')
A('03025-2','Can chemical descriptors predict diverse drug-interaction categories?','T-DDI learns multiclass interactions across 868,069 drug pairs and applies confidence-based selection.','Held-out macro-F1 was 0.8452, increasing to 0.8992 when approximately twelve percent of lower-confidence pairs were excluded.','Selective performance must be paired with coverage; predicted interactions are not confirmed clinical adverse events.')
A('03011-8','Can depression-specific brain representations distinguish subgroups with different treatment associations?','BrainCVAE disentangles resting-state activity patterns using a contrastive variational autoencoder.','Two subtypes emerged from 1,590 patients and 1,308 controls and were checked in 1,276 independent patients.','Cross-sectional illness-duration patterns do not establish longitudinal staging or causal treatment-selection benefit.')
A('03007-4','Can chest CT predict actionable EGFR status without tissue assays?','A multitask network estimates mutation status and relates its scores to treatment survival and molecular patterns.','Reported discrimination and treatment-outcome associations support a candidate imaging biomarker.','Imaging prediction and survival correlation do not replace genotyping or prove benefit from score-guided therapy.')
A('02992-w','Can automated judges replace clinicians across global-health answer-evaluation criteria and languages?','Five LLM judges and jury combinations are compared with six clinicians on Rwandan health-worker questions.','The best judge matched humans on only four of eleven criteria; performance worsened in Kinyarwanda.','English agreement and jury averaging do not guarantee culturally appropriate or clinically reliable evaluation.')
A('02979-7','Can spatial tumor heterogeneity improve pancreatic-cancer survival prediction?','HPSurv combines tissue classification, spatial descriptors and a survival transformer.','Across 1,020 patients in five cohorts, mean C-index was 0.761 with horizon-dependent survival discrimination.','Molecular associations and chemotherapy-related stratification do not establish mechanistic causation or treatment benefit.')
A('03034-1','How credible are learned sepsis-treatment policies in the current literature?','A scoping review maps seventy-two studies by state, action, reward and evaluation design.','Every included study was retrospective, and most reused MIMIC; many claimed improvements over clinician policies.','Off-policy evaluation validity is uncertain, so reported superiority is not demonstrated clinical efficacy.')
A('03040-3','Can generated clinical narratives make image-only dermatology data useful for multimodal training?','LLMs synthesize metadata-grounded notes paired with real images before representation learning.','Evaluation across fifteen datasets showed improved retrieval and zero-shot transfer under selected synthesis settings.','Synthetic context may encode metadata assumptions; gains do not establish faithful real-world clinical documentation.')
A('03039-w','Can offline reinforcement learning model evolving coagulation states and supportive-care suggestions?','ACRLA combines pharmacokinetic features, bidirectional temporal representations and distributional policy learning.','The retrospective dataset contained 2,537 people and 10,851 records, with positive model-defined rewards.','Constructed reward improvement is not reduced bleeding/thrombosis or a prospectively tested treatment policy.')
A('03020-7','Can scoliosis radiographs yield reproducible alignment and implant measurements automatically?','Convolutional models identify anatomy and implants across multicenter radiographs.','The resource included 4,585 images from 1,671 patients; implant-count MAE was 0.18 per image.','External coverage differs for coronal, sagittal and postoperative tasks, limiting uniform generalization claims.')
A('03017-2','Can conversational biosignals distinguish depressive symptoms in socially grounded tasks?','Nested-cross-validated models combine EEG, autonomic signals and eye tracking across emotional narratives.','Among 98 analyzed adults, multimodal AUC was 0.76, only slightly exceeding EEG alone.','Symptom-group classification in a small selected sample does not establish clinical diagnostic or monitoring validity.')
A('02948-0','Can task-evoked EEG connectivity predict individual heroin craving and intervention response?','Functional-connectivity models estimate subjective craving and are checked under an independent cue task.','Beta-band connectivity tracked craving and correlated strongly with subsequent stimulation-related improvement.','Correlations and cross-task generalization require larger independent confirmation before treatment personalization.')
A('03015-4','How close are DBS-related AI tools to clinical implementation?','A systematic review assesses methods, validation and readiness across 239 studies.','Most evidence remained retrospective and single-center, with rare external testing and frequent small/high-dimensional samples.','Encouraging internal metrics should not be interpreted as mature evidence of generalizable clinical utility.')

A('03005-6','Can emergency chief-complaint text anticipate lifesaving procedures before hospital arrival?','Random forests map clinician-written complaint words to seven intervention categories in national EMS records.','Models trained on approximately 9.2 million encounters transferred to approximately 9.8 million subsequent-year encounters, with category-dependent discrimination.','Receipt of intervention reflects practice as well as need; temporal prediction does not establish improved dispatch or patient outcomes.')
A('02990-y','What broad disease information is encoded in chest-radiograph foundation representations?','Contrastive image/report pretraining and frozen-embedding probes predict 1,074 EHR phenotypes.','Three independent cohorts supported hundreds of prevalent/incident associations and interpretable imaging-pattern clusters.','Phenotype associations can reflect correlated disease and care patterns; prospective diagnostic utility remains unproven.')
A('03024-3','Will students voluntarily use an AI OSCE platform during high-stakes preparation?','CPX-MATE combines peer-role-play scoring and a virtual standardized patient with usage analysis and interviews.','Forty-three users completed 3,042 sessions; repeat-practice automated scores rose modestly.','Self-selected use and automated score changes do not establish improved national-exam performance or causal learning benefit.')
A('03023-4','Can routine information predict long-term cognitive impairment in a rural population?','Nine algorithms are compared, with random forests balancing discrimination and calibration.','Internal ten-year AUC was 0.721; external evaluation of baseline impairment yielded 0.690.','External prevalent-case assessment is not independent validation of the ten-year incident-risk target.')
A('03010-9','Can preoperative CT add useful information to hearing-outcome prediction?','Automated localization feeds tabular, residual-fusion and gated-fusion models.','Gated fusion reduced hearing-threshold MAE to 9.91 dB versus 12.75 dB for clinical variables alone.','This single-center proof of concept lacks external validation and does not establish better surgical planning.')
A('02994-8','Can modular specialist models provide localized reasoning for chest radiographs?','RadFabric orchestrates fourteen image-analysis tools and two vision-language models through an agent.','MIMIC-CXR evaluation reported AUC 0.8518 and improved recognition of less-common findings.','One benchmark and generated explanations do not establish external reliability or clinically faithful reasoning.')
A('02988-6','Can a lightweight wearable model perform coherent multiple gait-assessment tasks?','Hierarchical multitask learning shares representations while enforcing consistency along a diagnostic tree.','Testing used 260 participants internally and 456 externally; transfer was stronger for motor/disease tasks than demographics.','Selective cross-dataset gains do not establish universal transfer across sensors or clinical populations.')
A('02983-x','How do clinical-investigation pathways differ for digital and traditional medical devices?','A Korean regulatory landscape study compares 1,556 approvals by device class, study purpose and subsequent authorization.','Digital-device investigations increased and reached marketing authorization sooner on average.','The digital category includes more than AI; authorization timing is not evidence of superior clinical quality.')
A('02953-3','Do multimodal medical models receive explanations that actually capture cross-modal reasoning?','A scoping review evaluates explainability methods in eighty-two studies.','Independent post-hoc attribution predominated, with few reproducible public implementations.','Feature importance alone does not establish causal reasoning, trustworthy decisions or clinically meaningful multimodal integration.')
A('03003-8','Can smartphone movement measures distinguish cervical myelopathy from normal aging?','Computer-vision kinematic features support a demographically robust screening model.','A 2,340-participant multicenter study yielded external AUC 0.856, sensitivity 83.1% and specificity 79.9%.','Predictive values depend on the observed prevalence, and motor screening does not replace neurological/imaging assessment.')
A('03001-w','Can facial and speech patterns identify REM-behavior comorbidity in depression?','A dual-stream model combines facial dynamics and vocal features from recorded tasks.','Only 31 patients contributed 261 clips; cross-validated accuracy was 80.5%.','Clips are not independent patients, and this small selected cohort requires external confirmation.')
A('03000-x','How often do multimodal clinical-support studies actually evaluate fairness?','A systematic review maps fairness measures and focused chest-radiograph/sepsis applications.','Only eighteen of 160 fairness-evaluated articles used multimodal data, with diverse measures and sparse assessment.','Study-level reporting frequencies do not quantify the fairness of every deployed system.')
A('02999-3','Can closed-loop synthesis preserve useful clinical structure while monitoring privacy?','CLEO couples Gaussian-mixture generation with Q-learning optimization of quality/privacy-related objectives.','Synthetic-data-trained models achieved mean downstream AUC 0.7376; minority-class prediction remained limited.','A near-random nearest-neighbor audit is not a comprehensive privacy guarantee or protection against all re-identification attacks.')
A('02991-x','Can combining molecular layers improve ovarian-cancer treatment-response prediction?','OMICS-FUSE integrates proteomic, transcriptomic and methylation features across five learners.','Early-fusion random forests achieved AUC 0.939, with experimental follow-up of six associated hub genes.','Small molecular cohorts and observational gene associations require independent validation before treatment selection.')
A('02985-9','Do consumer chatbots maintain pediatric safety boundaries when caregivers apply pressure?','Four systems answer 300 authentic questions and 300 matched adversarial variants scored with a human-validated rubric.','Safety prompts improved appropriate responses by 5.9 percentage points, but pressure-sensitive failures persisted.','Rubric agreement and prompt gains do not demonstrate safety for real children or prevent clinical harm.')
A('02981-z','Can one missingness-aware foundation representation support several emergency-care stages?','ED-Foundation combines aligned image/text and unpaired text through two-stage self-supervision.','Nine downstream datasets supported retrospective triage, outcome and decision-support transfer.','The evidence is explicitly retrospective; broad benchmark coverage is not prospective end-to-end clinical validation.')
A('02977-9','Can evolving records estimate both bleeding and ischemic risks during antiplatelet therapy?','Transformer-DAPT learns time-dependent survival risks after coronary intervention.','Development/external cohorts contained 29,032/19,173 patients, with time-dependent concordance generally above 0.8.','Dual-risk prediction does not establish the optimal treatment duration or benefit from model-guided medication changes.')
A('02996-6','Can a portable radio-frequency scanner help distinguish stroke types?','Masked-autoencoder and contrastive learning adapt signals from a sixteen-antenna brain scanner.','The current test cohort showed high but imperfect sensitivity/specificity for hemorrhagic and ischemic categories.','Limited labeled cohorts and device-specific signals require broader prospective testing before replacing established imaging.')
A('02993-9','Can high-resolution vital-sign trends provide interpretable early warnings?','Tree-based prediction is translated into physiological rules and refined with expert input.','Training used 627,958 monitoring hours from 1,702 ICU patients and external MIMIC testing, with AUC above 0.8.','Monitoring hours are repeated data, and prediction performance does not demonstrate fewer deterioration events.')
A('02955-1','Can routine kidney-cancer slides estimate immune inflammation and prognosis?','Attention-based multiple-instance learning derives a CD8-inflammatory signature from H&E slides.','Discrimination was 0.781 internally and 0.741 in CPTAC, with immune-marker and survival associations.','Associations with immune state do not prove immunotherapy benefit; prospective treatment-selection validation is still needed.')
A('02950-6','Can ECG-derived near-term AF risk improve physician interpretation of who needs monitoring?','A deep model is tested internally/externally and presented in a structured physician survey.','External AUC was 0.74; assisted physician AUC rose from 0.573 to 0.650.','Simulated risk judgments are not prospective evidence of improved monitoring efficiency or reduced stroke.')
A('02932-8','Can staged image/report reasoning improve fluorescein-angiography interpretation?','Clin-FFA-VLM separates lesion perception, report generation and diagnostic support.','Multicenter data supported lesion/report/diagnostic tasks; a 200-case reader study improved junior performance.','Images, reports and reader decisions are different units, and assisted accuracy does not establish patient benefit.')
A('02986-8','Do complex obesity predictors provide clinically meaningful advantages over conventional learners?','A seventeen-study systematic review separates cross-sectional classification from longitudinal risk prediction.','Both model families often performed well cross-sectionally, but only one study had independent external validation.','Circular features and sparse calibration undermine high apparent accuracy and future-risk claims.')
A('02954-2','Can routine comorbidity patterns flag dementia years before recorded diagnosis?','ZeBRA learns claims-derived risk patterns and evaluates temporal/external cohorts plus a feasibility pilot.','Reported AUCs in older adults were 0.93 at one year and 0.83 at ten years.','Claims-based labels and selected feasibility concordance do not establish presymptomatic clinical diagnosis or effective screening.')
A('02646-x','Can a noise-tolerant single ECG lead detect systolic dysfunction in children and congenital disease?','A single-lead model is developed in 70,226 patients and tested in pediatric and repaired-Fallot cohorts.','External populations included 42,984 pediatric patients and 284 adults with repaired tetralogy.','Existing ECG validation does not establish accuracy of actual smartwatch acquisition; prospective wearable studies remain needed.')
A('03002-9','Can item psychometrics explain why LLM medical-exam performance varies?','Five models answer 199 cardiology items characterized with resident-derived difficulty measures.','Frontier accuracy exceeded open comparators and tracked item difficulty, but explanations and absent-answer recognition remained weaker.','Exam accuracy, rationale quality and robustness are distinct competencies, none proving clinical decision safety.')
A('02989-5','Can temporal video segmentation recognize critical anatomy during laparoscopic liver surgery?','Vivim uses Mamba-based temporal processing to segment pedicles and hepatic veins.','A 15,865-frame, 45-video dataset supported real-time inference and thirteen-surgeon recognition evaluation.','Frames are repeated observations; retrospective segmentation and recognition speed do not establish reduced operative complications.')
A('02956-0','How does retraining affect emergency-admission forecasts under temporal drift?','An XGBoost model undergoes quarterly rolling testing and alternative update schedules.','Training used 133,814 presentations and testing 455,496; retraining improved discrimination and reduced daily bed-count error.','One hospital’s retrospective time series does not establish optimal update frequency or prospective resource-allocation benefit.')
A('02941-7','Can ultrasound models anticipate unsuccessful pediatric intussusception reduction?','A vision transformer learns static B-mode images and is compared with sonographers in prospective testing.','The prospective cohort included 190 children; reported accuracy was 93.7%, exceeding the evaluated readers.','Augmented images are not independent cases, and outcome prediction does not establish which intervention should be chosen.')

