 old=q.get('previous_review') or {};design={k:old[k] for k in ['design_group','collection','validation','patient_rct','reader'] if k in old}
 design['verification']='Prior article-level full-text design review' if old else 'not_adjudicated_from_current_extraction'
 limitations=[]
