 if design.get('patient_rct') is False and design.get('reader') is True:limitations.append('The evaluated units are reader interpretations rather than randomized patient outcomes.')
 elif design.get('design_group')=='retrospective':limitations.append('The reviewed design reuses existing data; retrospective predictive performance does not establish benefit from prospective AI-guided care.')
 elif design.get('design_group')=='review':limitations.append('The scale describes publications or evidence sources; it is not a pooled count of unique patients or independent clinical trials.')
 elif design.get('validation') is True:limitations.append('Prospective model evaluation measures prediction in new cases; it does not by itself establish benefit from AI-guided treatment.')
 if not limitations:limitations.append('Article-specific causal and deployment limitations have not been manually adjudicated in this source-extracted profile; consult the linked Discussion and study design.')
 question=q.get('research_problem');method=q.get('ai_method') or 'AI method requires source-level resolution'
 # Factual enrichment beyond a method-class label. Candidate component roles
