  out['experiment_scale']=[{'value':value,'unit':unit,'role':r,'context':r,'verified':True,'source_section':'Manually inspected Abstract and relevant Methods/Results','source_url':pdf if source_kind=='publisher_pdf' else link('Methods'),'verification':'manually_interpreted_fulltext_sections'} for value,unit,r in v['counts']]
  out['scale_status']='manually_interpreted' if v['counts'] else 'not_applicable_primary_cohort';out['study_design']={**v['study_design'],'verification':'Manual interpretation of relevant full-text design/results sections'}
