def main():
 rows=load(ROOT/'data/reviews/npj.json',[])
 with concurrent.futures.ProcessPoolExecutor(max_workers=4) as pool:profiles=list(pool.map(enrich,rows,chunksize=8))
 target=ROOT/'data/enrichment/npj.json';target.parent.mkdir(parents=True,exist_ok=True)
 assert len(profiles)==len(rows) and len({p['id'] for p in profiles})==len(profiles)
 assert all(p['research_problem'] and p['ai_method'] and p['study_summary'] and p['limitations'] for p in profiles)
 assert not any('abstract' in p or 'raw_source' in p for p in profiles)
 # Readers see either the previous complete version or the next complete one.
 temporary=target.with_suffix('.json.tmp');temporary.write_text(json.dumps(profiles,ensure_ascii=False,indent=2));os.replace(temporary,target)
 print(json.dumps({'profiles':len(profiles),'review_levels':dict(collections.Counter(p['review_level'] for p in profiles)),'with_scale':sum(bool(p['experiment_scale']) for p in profiles),'manual_fulltext_profiles':sum(p['verification']['human_fulltext_interpretation'] for p in profiles),'with_research_sections':sum(bool(p['verification']['research_sections_available']) for p in profiles),'with_datasets':sum(bool(p['datasets']) for p in profiles),'with_metrics':sum(bool(p['metrics']) for p in profiles)}))
if __name__=='__main__':main()
